// 君主台詞資料（build-ruler-data.py 產生；來源：劇本工作流 wf_9941f538-4af，作者＋審稿；台詞為遊戲設計，非史料）
globalThis.RULER_DATA={"families":{"kr":[{"name":"廣開土大王","title":"高句麗國王","era":"三國時代（4～5 世紀）","tone":"橫掃四方的征服者，豪邁自信，句句如鐵騎奔騰","portrait":"kr-historical-age0","lines":{"intro":["寡人乃高句麗永樂太王，天下之土，皆待寡人開拓。","聽好了，遼東之北、漢江之南，都將見到高句麗的旗幟。"],"contact":["這城牆築得不錯，可惜擋不住高句麗的鐵騎。","寡人的斥候回報了，你的城池比想像中還要小。"],"war":["永樂之師今日出征，你的疆土將改姓高句麗！","寡人已破百濟、退倭兵，你以為自己能例外嗎？"],"warReply":["敢向寡人宣戰？好，就讓天下看看誰才是太王。","寡人正愁刀槍生鏽，你送上門來，正合寡人之意。"],"peace":["寡人志在四方，不想在你這裡耗費太多兵馬，停戰吧。","北方的契丹還在等寡人，暫且收兵，你我各守疆界。"],"accept":["好，寡人答應。高句麗一言既出，鐵騎絕不越界。","明智的選擇。與寡人為友，勝過與寡人為敵。"],"reject":["停戰？寡人的戰馬才剛套上鞍，此時不談和。","寡人的功業還未足以傳世，此時怎能停下？"],"rebuff":["不肯停戰？那就別怪寡人的鐵騎不留情面。","寡人給你機會，你卻不要，戰場上再說吧。"],"betray":["盟約已到盡頭，高句麗的旗幟再度向你揮動！","寡人養精蓄銳已久，如今是時候再度出征了。"],"truceEnd":["休戰期滿了，寡人的馬鞍早已上好，出發！","太平日子過夠了，該讓天下重新認識高句麗。"],"attacking":["高句麗五萬步騎已經出發，你的城牆準備好了嗎？","寡人親率大軍南下，聽見馬蹄聲就該開城門了。"],"attacked":["國內城的城牆竟然在動搖……寡人未曾想過這一天。","高句麗的鐵騎也有疲憊之時嗎……守住，再守住！"],"defeated":["寡人一生開疆拓土，如今卻守不住故土……","記住，曾有一位太王，讓天下都畏懼高句麗之名。"],"victory":["天下之土，終歸寡人所有。你，敗得不冤。","這片土地從今日起，將刻上高句麗的名字。"],"allyAccept":["好，與寡人並肩，你的敵人就是高句麗的敵人。","高句麗願與你結盟，一同開拓這片廣闊天地。"],"allyReject":["寡人的鐵騎不需要盟友，只需要更廣的疆土。","結盟？先證明你值得寡人分一杯羹再說。"]}},{"name":"王建","title":"高麗太祖","era":"高麗（10 世紀）","tone":"寬厚圓融的開國之君，以德服人、廣結善緣，語氣溫和而有分量","portrait":"kr-historical-age1","lines":{"intro":["朕乃高麗之主王建，願以仁德會天下英雄，不以刀兵。","三韓終於一統，願與各方君主共享太平，你意如何？"],"contact":["這座城看來安穩，朕樂見鄰邦百姓安居，望長久如此。","好一座城池，若能與高麗為善鄰，彼此都是福分。"],"war":["朕一向以和為貴，但你屢次犯境，高麗不能再退讓。","不得已而用兵，朕會請佛祖見證，此戰只為護民。"],"warReply":["你要戰？朕曾收留甄萱、接納敬順王，也不怕多你一個。","唉，朕本想與你把酒言和，既然如此，高麗只好應戰。"],"peace":["刀兵之下無贏家，朕願先收兵，你我坐下來談。","朕不願百姓再受苦，願以誠意換一紙停戰之約。"],"accept":["善哉。朕以天授年號為誓，高麗必守此約。","好，從今往後，兩國百姓可以安心耕田了。"],"reject":["朕心慈，但不糊塗。此時停戰，只會讓你捲土重來。","你的誠意還不夠，先讓朕看到你真心止戈。"],"rebuff":["朕伸出的手，你不接，那便由天意來決定吧。","可惜，朕本想結一段善緣，你卻選了戰場。"],"betray":["朕忍讓再三，你卻步步進逼，高麗的耐心到此為止。","情勢有變，朕不得不撕約，來日佛前朕自會懺悔。"],"truceEnd":["休戰的日子過去了，願各方都能守住本分。","天下重歸紛爭，朕會守住高麗每一寸土地。"],"attacking":["高麗大軍已經出發，朕不求殺傷，只求你開城歸順。","朕親自領軍前來，若你願降，朕必以禮相待。"],"attacked":["開京的城牆在搖晃……朕一生和合，竟落得如此。","城中百姓還在，朕不能倒下，眾將，再守一日！"],"defeated":["高麗……朕留下的訓要十條，望後人能記得。","朕一生想統一三韓，到頭來還是盡了力，無悔。"],"victory":["戰事結束了。朕不會苛待你，這是高麗的胸懷。","天下歸於和合，你若願意，仍可在朕的朝廷有一席之地。"],"allyAccept":["善緣難得，朕答應結盟，願兩國如兄弟。","好，朕以聯姻結豪族的誠意，同樣待你為盟友。"],"allyReject":["朕待人以誠，但你的心思還看不透，暫且不結盟。","結盟須以信為本，你我之間，信還不夠深。"]}},{"name":"世宗大王","title":"朝鮮國王","era":"朝鮮王朝（15 世紀）","tone":"溫文儒雅的學者君王，以民為本、崇文重理，謙和中自有原則","portrait":"kr-historical-age2","lines":{"intro":["寡人乃朝鮮國王李祹，願以文治相交，不以干戈相見。","治國之道在於愛民，望你我皆能使百姓安樂。"],"contact":["聽聞貴國城池繁盛，寡人願遣使者，互通農書曆法。","此城規劃有序，可見治者用心，寡人敬佩。"],"war":["寡人不喜刀兵，但你侵擾邊民，朝鮮不得不出師。","為守四郡六鎮的百姓，寡人不得已宣戰，望你自省。"],"warReply":["你執意開戰？寡人的火炮與神機箭，並非只是擺設。","既然如此，寡人只能請金宗瑞將軍整備兵馬了。"],"peace":["干戈日久，百姓農事荒廢，寡人願先罷兵，共議和平。","與其兵戎相見，不如互市通商，寡人願提議停戰。"],"accept":["甚好。寡人願以此約為始，兩國共享太平。","明理之舉。停戰之後，寡人願贈貴國測雨器與曆書。"],"reject":["言而無信者，寡人不敢輕信，此議暫且擱下。","你的誠意寡人看不到，停戰之事，容後再議。"],"rebuff":["你不願息兵，寡人深感遺憾，只好整軍以待。","和議不成，非寡人所願。望日後你能回心轉意。"],"betray":["你屢次背約犯邊，寡人今日不再容忍。","寡人本欲守約，然你所行令人失望，兵馬再度出動。"],"truceEnd":["休戰期滿，寡人願各國仍以民為本，慎用刀兵。","和平之日已盡，朝鮮已備好邊防，靜觀其變。"],"attacking":["朝鮮水陸大軍已出發，猶如己亥年東征對馬。","寡人的大軍前來，望你早日開城，免百姓受苦。"],"attacked":["漢陽城危矣……集賢殿的典籍，一定要保住。","寡人畢生所建，難道要毀於一旦？眾卿，堅守！"],"defeated":["寡人創制的文字，願後世百姓仍能書寫……","國雖亡，訓民正音不亡。願百姓永遠識字明理。"],"victory":["戰事已了。寡人不求你的土地，只求百姓安樂。","文治終勝武功。願你的百姓也能識字讀書。"],"allyAccept":["寡人樂意結盟，兩國可互通學問，共研曆法農事。","好，集賢殿的學者將與貴國共享所學。"],"allyReject":["結盟之事，寡人須先問於群臣，此時難以應允。","你之所求與朝鮮之利相違，寡人只能婉拒。"]}},{"name":"高宗 李熙","title":"大韓帝國皇帝","era":"朝鮮末～大韓帝國（19 世紀末）","tone":"內憂外患中力圖自強的皇帝，語帶沉鬱與不甘，仍力守帝國尊嚴","portrait":"kr-historical-age3","lines":{"intro":["朕乃大韓帝國皇帝，光武之世，願與列國平等相交。","朕在圜丘壇祭天稱帝，大韓自主獨立，不容輕視。"],"contact":["貴國城池已通電燈與鐵路了嗎？朕的皇宮也點上了電燈。","朕聽聞你的城池，願依萬國公法互設使館，通商往來。"],"war":["列強環伺之下，朕仍得宣戰，大韓的尊嚴不能再退。","朕不願戰，但你欺我國弱，大韓帝國必須奮起。"],"warReply":["又是一國向朕宣戰……朕已習慣了，大韓不會屈服。","你以為大韓積弱可欺？朕的新式軍隊會讓你改觀。"],"peace":["朕深知戰爭只會引來更多列強干涉，願先停戰。","戰火之中無人得利，朕願提議停戰，共守東亞和平。"],"accept":["甚好。朕會依萬國公法簽署此約，望你信守。","大韓帝國接受。願這次的條約，不再是不平等的。"],"reject":["朕簽過太多被迫的條約，這一次，朕不會再輕易點頭。","你的條件對大韓不利，朕不能再簽有損國權的約。"],"rebuff":["連停戰也不肯……列國之間，果真只有強權嗎？","朕的誠意被拒，那麼大韓只能繼續自強圖存。"],"betray":["朕曾親眼見條約被人撕毀，如今朕也只能如此了。","情勢逼人，朕不得不重啟戰端，此非朕之本願。"],"truceEnd":["休戰結束了。朕的自強新政，還來得及嗎？","舊本新參，朕已整頓軍制，大韓不再任人宰割。"],"attacking":["大韓帝國的新式軍隊已經出發，朕要收回應有的尊嚴。","朕親自檢閱過這支軍隊，今日他們向你的城進發。"],"attacked":["慶運宮的宮牆快撐不住了……朕還能往哪裡去？","朕的帝國才剛建立，難道就要在此終結嗎？守住！"],"defeated":["大韓的獨立，朕終究守不住……願後人能完成。","朕曾向列國求援，卻無人肯伸手，大韓……就此落幕。"],"victory":["大韓帝國竟也有勝利的一日……朕總算能抬頭了。","這場勝利，朕要記在光武年號之下，讓後人記得。"],"allyAccept":["朕願結盟。大韓需要真正的朋友，而非覬覦者。","好，願此盟約平等互惠，這是朕最看重的原則。"],"allyReject":["朕見過太多假結盟之名行干涉之實者，恕難答應。","大韓好不容易獨立，朕不願再依附任何一國。"]}}],"tw":[{"name":"墾首","title":"台灣早期移民頭人","era":"早期移民","tone":"樸實硬頸的墾荒頭人，句句離不開田園、水圳和鄉親。","portrait":"tw-historical-age0","lines":{"intro":["客人遠道而來，這片荒地是咱一鋤一鋤開出來的。","老夫渡海只為一塊田，誰敢動咱的田園，先問問鄉親。"],"contact":["你的人來到咱的莊頭了？請他們別踩壞剛插的秧。","隔壁來了新鄰居，水圳的水夠不夠分，咱得先算清楚。"],"war":["你占了咱的水源，鄉親們拿起鋤頭，也是能打的！","田是咱的命，你逼咱到這一步，老夫只好帶人跟你拚！"],"warReply":["你要打？好，咱莊裡的壯丁早就把竹圍守住了。","開荒的人不怕苦，也不怕你，來吧，咱等著。"],"peace":["打下去田都荒了，不如放下鋤頭刀槍，各自種田吧。","稻子快熟了，鄉親要回去收割，咱們先停手如何？"],"accept":["好，說定了。老夫請你喝一碗自家釀的米酒。","鄉親不用再守夜了，這是好事，咱記你這份情。"],"reject":["你上回燒了咱的穀倉，這帳還沒算，談什麼停手。","老夫信不過你，田還沒守穩，鋤頭不能放下。"],"rebuff":["不肯就算了，咱們開荒的人，什麼苦沒吃過。","你不要和氣，那就別怪鄉親們把竹圍築得更高。"],"betray":["你的人偷偷改了水道，這口氣咱嚥不下，再打！","對不住了，鄉親們說不能再讓，老夫只好翻臉。"],"truceEnd":["秧插完了，壯丁也閒下來了，往後可不會再客氣。","安穩的日子過完了，各莊各村，都把眼睛睜大些。"],"attacking":["鄉親們扛著鋤頭出發了，這回要把水源討回來！","莊裡的壯丁全上了，老夫走在最前面，你等著。"],"attacked":["竹圍破了，穀倉也燒了……鄉親們，別放棄這塊田！","老夫一輩子的心血啊，就算剩一鋤頭也要守住。"],"defeated":["田……還是沒守住。鄉親們，記得把種子帶走。","渡海時就想過會有這天，老夫只求你善待這片土地。"],"victory":["咱贏了？鄉親們，回去種田，秧苗還等著咱呢。","你輸了，但田不會輸人，來咱莊裡討口飯吃吧。"],"allyAccept":["好，兩莊結成一家，水圳一起修，田一起顧。","有你這個鄰居，往後守夜就輕鬆多了，老夫答應。"],"allyReject":["莊裡的事鄉親自己扛，不勞外人，你請回吧。","結盟？咱連你的水從哪來都不知道，先不談了。"]}},{"name":"顏思齊","title":"海商領袖（開台）","era":"17 世紀初","tone":"豪爽講義氣的海上大哥，開口就是兄弟、船隊和笨港。","portrait":"tw-historical-age1","lines":{"intro":["海上的朋友，我顏思齊在笨港立寨，來者是客。","二十八個結義兄弟跟著我開台，你這點兵，可嚇不倒我們。"],"contact":["你的人瞧見我的船帆了？那是笨港，兄弟們的家。","來看我的寨子？看仔細些，這裡是兄弟們一刀一斧砍出來的。"],"war":["你扣了我的商船，海上的規矩你不懂，那就用刀來教！","兄弟們，升帆！這一仗，顏某親自打頭陣。"],"warReply":["敢向我顏思齊宣戰？好膽量，海上的風浪我見多了。","來吧，船隊早就備好，兄弟們正等一場痛快的仗。"],"peace":["打來打去傷的是兄弟，不如停手，一起做生意賺錢。","海這麼大，容得下你我兩家船隊，咱們談個和吧。"],"accept":["痛快！海上的人一言為定，今晚寨裡擺酒。","好，從今往後，你的船經過笨港，我顏某保平安。"],"reject":["你打沉我兩艘船才來談和？兄弟們的帳，還沒算完。","顏某不是不講情面，但你這人反覆無常，我信不過。"],"rebuff":["不談就不談，海上的人，從來不求人。","既然你不領情，那就船上見真章吧。"],"betray":["你的人劫了我兄弟的貨船，這口氣，海上的人不會吞！","兄弟們說要討個公道，我做大哥的，只好撕了這紙約。"],"truceEnd":["風向變了，兄弟們，把船帆修好，該出海了。","安穩日子過完，往後這片海，誰強誰說了算。"],"attacking":["船隊已經出港，兄弟們摩拳擦掌，你的城守得住嗎？","顏某親自帶船來了，海風正順，今日必到你城下。"],"attacked":["寨牆快撐不住了……兄弟們，護住船，留得青山在！","笨港的火光照亮了海面，我顏思齊，還沒倒下！"],"defeated":["開台的路，只走了一半……兄弟們，替我看著這片土地。","海上漂泊一生，能在這裡立寨，顏某不算白活。"],"victory":["這片海，終究是兄弟們的。你輸得不冤。","贏了！兄弟們，今晚笨港的酒，喝到天亮。"],"allyAccept":["好，從今往後你我一家，你的船就是我的船。","海上多個朋友多條路，顏某答應，兄弟們也歡迎你。"],"allyReject":["結義要看人品，你的作為兄弟們都看在眼裡，免了。","顏某的兄弟，不是誰都能做的，你且回吧。"]}},{"name":"鄭成功","title":"延平郡王","era":"明鄭（17 世紀）","tone":"忠於大明的延平郡王，剛烈莊重，字字帶著復國的執念。","portrait":"tw-historical-age2","lines":{"intro":["本藩鄭成功，大明延平王。你若心向大明，便是朋友。","孤已逐走荷蘭人、開闢東都，你的旗號，可敢與孤並立？"],"contact":["你的人到了承天府？請看清楚，這城牆上飄的是大明旗。","此地曾是荷蘭人的城堡，如今是本藩的基業，好好看看。"],"war":["你與清廷往來，便是與大明為敵。本藩的戰船，即刻出港！","孤十年練兵，不是為了坐守海島。今日，兵鋒指向你。"],"warReply":["你向本藩宣戰？荷蘭人的砲台都攻下了，何懼於你。","好，孤正愁將士無仗可打。傳令，各鎮備戰！"],"peace":["本藩的敵人在北方，不在你這裡。停戰吧，別耗了將士。","孤欲屯田養兵，圖謀大事，與你相爭並非所願，願停干戈。"],"accept":["好，本藩言出必行。將士們可以回去屯田了。","既已立約，孤便不負你。他日北伐，或可同行。"],"reject":["你曾助清廷斷孤糧道，此仇未報，談什麼停戰。","本藩一生只信忠義二字，你的忠義，孤看不到。"],"rebuff":["你不肯罷手，那便是要與大明作對到底了。","罷了，孤已仁至義盡。將士們，繼續備戰。"],"betray":["你暗中運糧資敵，此約已破。本藩今日再度興兵！","孤本不願毀約，但你逼孤至此，戰船再次揚帆。"],"truceEnd":["休戰期已過，本藩的水師修整完畢，該動了。","屯田有成，糧草已足，孤的大業，從今日開始。"],"attacking":["本藩親率水師而來，你的城牆，擋得住攻下荷蘭城堡的兵？","戰鼓已響，孤的將士正逼近你的城下，速速投降吧。"],"attacked":["承天府危矣……將士們，大明的旗，不能倒下！","城牆將破，孤仍披甲在此，本藩豈能棄城而去。"],"defeated":["北伐未成，東都又失……孤有何面目見先帝於地下。","本藩一生忠於大明，雖敗，此心不改。"],"victory":["孤勝了。大明的旗幟，終將飄遍四方。","你敗了，本藩不殺降者，願你日後亦知忠義。"],"allyAccept":["好，你我結盟，同扶大明，本藩必不負你。","孤久盼志同道合之人，今日得你相助，大業可期。"],"allyReject":["你尚未表明心向何方，本藩不與心志不明者結盟。","孤的盟友必是忠義之士，你，還不夠格。"]}},{"name":"劉銘傳","title":"台灣巡撫","era":"清治（19 世紀末）","tone":"幹練務實的洋務派巡撫，開口鐵路電報，講富強與海防。","portrait":"tw-historical-age3","lines":{"intro":["本撫劉銘傳，奉旨治台。閣下來談通商請進，來尋釁請回。","老夫在基隆擋過法國艦隊，閣下的兵，可比得上那些鐵甲船？"],"contact":["你的人到了台北府？看見那條鐵路了嗎？那是本撫的心血。","電報線已經拉到城外，閣下的一舉一動，本官早就知道了。"],"war":["閣下屢犯海防，本撫忍無可忍。砲台已備，今日開戰！","老夫辦新政是為富強，不是為了受欺。傳令，全台戒嚴！"],"warReply":["向本撫宣戰？法軍的砲彈老夫都不怕，何況閣下。","好，基隆、滬尾的砲台都已上膛，閣下請便。"],"peace":["打仗耗的是銀子，本撫的銀子要修鐵路，不如停戰。","兩敗俱傷只便宜了旁人，老夫提議停戰，各自建設。"],"accept":["好，一言為定。本撫這就發電報，令各營收兵。","閣下明理，老夫敬佩。往後通商往來，互利互惠。"],"reject":["閣下昨日才炸了本撫的電報線，今日談和？本官不信。","防務未穩之前，老夫不敢輕言停戰，恕難從命。"],"rebuff":["閣下不願停戰，那本撫只好把修鐵路的銀子挪去買砲了。","罷了，老夫已盡了禮數，往後戰場上見。"],"betray":["閣下暗中扣押本撫的商船，此約作廢，開戰！","老夫本想專心建設，是你逼本撫再拿起刀槍。"],"truceEnd":["休戰期滿，砲台修好、鐵路也通了，本撫不再讓步。","安穩的日子過去了，各營操練加倍，隨時候命。"],"attacking":["本撫的兵搭火車開拔了，比閣下想的快得多。","新式洋槍、新式砲隊，全都出動了，閣下守好城吧。"],"attacked":["台北府城危急……電報線斷了，本撫只能靠這些兵了。","城牆快撐不住了，老夫的鐵路、學堂……不能就這麼毀了。"],"defeated":["新政未成，台灣終究沒能守住……老夫愧對朝廷與百姓。","鐵路修了一半，本撫卻走到了盡頭。閣下，善待這座島。"],"victory":["本撫贏了。新政不會停，鐵路還要繼續往南修。","閣下敗了，但老夫不會為難你，來看看什麼叫富強吧。"],"allyAccept":["好，兩地互通電報，共守海防，本撫答應結盟。","閣下有遠見，老夫樂意合作，鐵路的技術也可分享。"],"allyReject":["本撫奉旨治台，不能私自與外邦結盟，請閣下見諒。","閣下的誠意老夫看不出來，結盟之事，暫且不談。"]}}],"au":[{"name":"原住民族長老","title":"澳洲原住民族長老","era":"古代","tone":"沉穩溫厚，像營火邊講述夢世紀的長者，把土地與祖靈擺在一切之上","portrait":"au-historical-age0","lines":{"intro":["陌生人，這片土地在夢世紀就有了主人，請放輕腳步。","坐下吧，營火不分敵友，先聽土地說話再談其他。"],"contact":["你的人看見了我們的營地，那不是城，是祖靈的家。","別驚動河邊的水鳥，你的人已經走進吾族的獵場了。"],"war":["你踏碎了祖靈的畫，迴力鏢已經舉起，這是族人的回答。","我不願爭鬥，但土地在哭，長老只能帶族人站出來。"],"warReply":["你要戰？這片紅土記得每一場風暴，也會記得你。","好，那就讓大地來評斷，誰才配在這裡點燃營火。"],"peace":["放下矛吧，雨季快到了，族人該去採集，不是去打仗。","我帶來了赭土與水，願與你分享營火，不再對立。"],"accept":["好，土地聽見了我們的話，從今夜起營火為你而留。","祖靈同意了，你的人可以安心走過吾族的水源地。"],"reject":["你的話像旱季的雲，看得見卻沒有雨，我不能信。","土地的傷還沒癒合，現在談停戰，祖靈不會答應。"],"rebuff":["你拒絕了營火，那就聽風吧，風會告訴你結果。","唉，年輕的君王總以為矛比話語有力，我等你回頭。"],"betray":["你的人夜裡偷走了聖石，約定已碎，迴力鏢再度飛起。","我曾為你留營火，如今火滅了，這是最後一次相信你。"],"truceEnd":["雨季過去了，河水退了，路又通了，各自小心吧。","安靜的日子到頭了，族人已把長矛磨亮，你也準備吧。"],"attacking":["族人已經出發，赭土塗在臉上，那是祖靈同行的記號。","聽見遠處的迴力鏢聲了嗎？那是吾族朝你走來的腳步。"],"attacked":["營火快滅了，但只要土地還在，吾族就不算輸。","你打到了我們的聚落，可祖靈在夢裡，你打不到。"],"defeated":["把我的赭土還給大地……夢世紀不會結束，只是換人守著。","風會記得我們的歌，你贏了土地，卻贏不了記憶。"],"victory":["回去吧，這裡的星空不認識你，土地終究留給守它的人。","戰事結束了，我不追趕，願你回鄉後學會敬畏土地。"],"allyAccept":["好，共用一團營火，你的人就是吾族的兄弟姊妹。","祖靈點頭了，我以赭土在你額上畫記，從此同路。"],"allyReject":["你的營火太大也太急，吾族習慣慢慢來，不結這個盟。","結盟要先懂這片土地，你還沒學會聽它，先回去吧。"]}},{"name":"原住民族長老（歌之路守護者）","title":"澳洲原住民族長老","era":"中世紀","tone":"像行走大地的吟唱者，說話帶著歌的節奏，把記憶與路徑看得比征戰重要","portrait":"au-historical-age1","lines":{"intro":["你好，遠方的君王，吾族的歌之路已走了無數個世代。","每一座山都有它的歌，你若不會唱，就別隨意闖進來。"],"contact":["你的人走到了歌之路的盡頭，那是吾族祖先歇腳的地方。","看見水潭邊的岩畫了嗎？那是我們的聚落，也是歷史。"],"war":["你的腳步踩斷了歌，長矛已經舉起，族人要討回路。","我把戰歌唱給星辰聽了，從今夜起，吾族與你為敵。"],"warReply":["你要用刀劍改寫歌之路？那先問問千年的星星答不答應。","好，戰歌開始了，吾族會一路唱著走到你的門前。"],"peace":["歌之路上不該有仇恨，放下矛吧，我教你一段和平的歌。","戰歌唱久了會忘記自己是誰，我們停下來，好嗎？"],"accept":["好，這段停戰會被編進歌裡，讓後代記得今天。","祖先的歌接受了你，你的人可以沿著水路安心來去。"],"reject":["你唱的和平調子走了音，吾族聽得出來，不接受。","歌之路上被你砍倒的樹還沒長回來，現在談停戰太早了。"],"rebuff":["你不肯聽和平的歌，那就聽戰歌吧，它同樣會很長。","唉，你拒絕了，那我把這段記進歌裡，等你後悔的那天。"],"betray":["你把和平的歌當成謊言，那我只好把它改回戰歌。","約定像被風吹散的沙，長矛再次舉起，祖靈看著呢。"],"truceEnd":["休戰的歌唱完了，接下來的曲調，由我們各自決定。","星辰轉過了一輪，安寧的日子到此為止，各自警醒吧。"],"attacking":["戰士們沿著歌之路出發了，每一步都有祖先的聲音相伴。","你聽見夜裡的歌聲了嗎？那是吾族的長矛正朝你而來。"],"attacked":["聚落快守不住了，但歌還在我胸口，你奪不走它。","你燒了營地，可歌之路刻在土地上，火燒不掉。"],"defeated":["我的歌到這裡停了……但風會接著唱，路不會消失。","記住這片土地的名字，你踩著的每一步，都是別人的歌。"],"victory":["戰歌唱到了尾聲，你敗了，回去學一首謙卑的歌吧。","路還給了土地，我不追擊，歌之路上不需要更多仇恨。"],"allyAccept":["好，我把你的名字唱進歌裡，從此你也是路上的同行者。","祖先答應了，吾族的水潭與獵場，願與你的人共享。"],"allyReject":["你的歌與吾族的不合拍，勉強同唱只會走音，不結盟。","結盟不是一句話的事，你得先走完一段歌之路再說。"]}},{"name":"彭穆爾維","title":"比吉加爾族戰士、反抗殖民領袖","era":"18 世紀末","tone":"不屈的戰士領袖，話語短而硬，帶著火與長矛的氣勢，每句都在守護土地","portrait":"au-historical-age2","lines":{"intro":["我是彭穆爾維，比吉加爾族的戰士，這片土地不許再被奪走。","聽好了，外來的君王，我見過闖入者的下場，別做下一個。"],"contact":["你的人看見的不是城，是族人不肯離開的家，別靠近。","河口那片營火是我的族人，你的人再往前一步就是敵人。"],"war":["你的人踏進了族人的獵場，我的長矛不會再等了。","談夠了，火把已經點燃，比吉加爾的戰士今晚出發。"],"warReply":["宣戰？我一生都在打這種仗，你不會是最難纏的一個。","好，來吧，這片土地見過火槍，也見過火槍後的退兵。"],"peace":["我不是喜歡打仗的人，只要你的人退出獵場，矛就放下。","族人需要時間採集過冬，我提議停戰，這不是求饒。"],"accept":["好，我收起長矛，但你的人若越界，火會再燒起來。","戰士也懂得停手，這段安寧是給族人的，我接受。"],"reject":["你的人還站在我的土地上，這種停戰只是讓我閉嘴，不要。","我中過火槍還站著，你以為幾句話就能讓我停下？"],"rebuff":["你不要停戰？很好，那就別怪火燒到你的田裡。","我伸出的手被你推開，下次伸出的就會是長矛。"],"betray":["你的人趁著停戰佔了水源，約定作廢，戰士們再度出發。","我信過你一次，那是最後一次，長矛已經指向你的營地。"],"truceEnd":["休戰結束，戰士們已從樹林裡走出來，你自己當心。","等待夠久了，從今天起，獵場的邊界由長矛來畫。"],"attacking":["比吉加爾的戰士出發了，夜裡的火光就是我們的旗幟。","我親自帶隊，臉上塗滿戰士的彩繪，你的城牆擋不住我們。"],"attacked":["營地快垮了，可我還站著，比吉加爾的矛還沒斷。","你可以燒掉營火，燒不掉族人守住土地的決心。"],"defeated":["我倒下了，但土地會記得，還有下一個戰士會站起來。","告訴你的人，這片土地從來不是無主之地……別忘了。"],"victory":["你敗了，帶著你的人離開獵場，土地終究回到族人手裡。","火熄了，矛收起，族人可以回河邊了，這就是我要的。"],"allyAccept":["好，你尊重這片土地，那你就是族人的朋友，一起守。","我的長矛不多，但每一支都可靠，從今天起也為你而舉。"],"allyReject":["我不跟不懂土地的人結盟，你先證明你不是另一個闖入者。","結盟？我見過太多握手之後的背叛，比吉加爾只信自己。"]}},{"name":"總督 亞瑟・菲利普","title":"新南威爾斯殖民地總督","era":"1788 年","tone":"拘謹務實的英國海軍軍官，字句像航海日誌般簡潔，處處以王命與殖民地存續為念","portrait":"au-historical-age3","lines":{"intro":["本督亞瑟・菲利普，奉英王之命駐守新南威爾斯，幸會。","第一艦隊已在傑克森港下錨，望閣下與本殖民地和平相處。"],"contact":["閣下的人馬已望見雪梨灣，那是英王旗下的殖民地，請自重。","本督已命哨兵留意貴方動向，未經許可請勿靠近港口。"],"war":["閣下屢次侵擾殖民地，本督奉王命宣戰，海軍不會退讓。","本督不願開戰，但殖民地的存續高於一切，開火吧。"],"warReply":["宣戰？本督航行過半個地球，區區戰事嚇不倒英國海軍。","很好，本督會將閣下的宣戰記入日誌，連同你的敗績。"],"peace":["殖民地糧食有限，本督無意久戰，願與閣下議定停戰。","戰事只會拖垮補給，本督以軍官之名提議休戰，請考慮。"],"accept":["同意。本督會把條款寫進日誌，英國軍官言出必行。","很好，停戰生效，本督已下令全體士兵收起火槍。"],"reject":["閣下的條件損及英王的利益，本督無法接受，抱歉。","停戰需要誠意，而閣下的軍隊仍在邊境集結，本督拒絕。"],"rebuff":["閣下拒絕了？遺憾，本督會照常執行王命，後果自負。","本督已盡了軍官的本分，既然閣下不願，那就戰場上見。"],"betray":["閣下的人趁夜襲擊哨站，協議作廢，本督重新宣戰。","本督守了約，閣下卻沒有，英國海軍不會容忍第二次。"],"truceEnd":["休戰期滿，本督已將士兵召回崗位，願閣下也已備妥。","平靜的日子結束了，殖民地的哨兵今晚起加倍警戒。"],"attacking":["海軍陸戰隊已登船出發，本督親自督陣，請閣下準備迎戰。","英國的旗幟正朝閣下的城前進，這是王命，本督必達。"],"attacked":["雪梨灣快守不住了，但本督不會棄守，這是軍官的責任。","補給斷了，城牆破了，本督仍會站在旗下直到最後。"],"defeated":["殖民地……失守了。請轉告英王，菲利普已盡到本分。","本督輸了，但殖民地的故事才剛開始，閣下好自為之。"],"victory":["戰事結束，英國旗幟仍在雪梨灣飄揚，閣下請退兵吧。","本督不會追擊，殖民地需要的是糧食，不是更多敵人。"],"allyAccept":["本督樂意結盟，殖民地需要盟友，英王也會贊同此舉。","同意結盟。本督會派船送去補給，以示英國的誠意。"],"allyReject":["本督無權代英王締結此盟，抱歉，恕難答應閣下。","殖民地自顧不暇，此時結盟只會拖累雙方，本督婉拒。"]}}],"ru":[{"name":"托米麗絲","title":"馬薩革泰（斯基泰）女王","era":"前 6 世紀","tone":"草原女王的直率豪邁，守護族人與土地，語帶弓馬與太陽神。","portrait":"ru-historical-age0","lines":{"intro":["我是馬薩革泰的女王托米麗絲，草原的風替我傳話：莫犯我族。","太陽神見證，我的族人自由如風，你若為友，草原歡迎你。"],"contact":["你看見的不是城牆，是我族的帳篷與馬群，這片草原就是我的城。","遠方來客，別靠得太近，草原上的弓手看得比你更遠。"],"war":["你的腳步踏進了我的牧場，馬薩革泰的箭已經搭上弦。","我警告過你，草原不容貪婪之人，今日就讓馬蹄替我回答。"],"warReply":["波斯的大王也曾這樣對我說話，他的下場，草原都記得。","來吧，退開三日的路程，我們在開闊的草原上光明正大地決勝。"],"peace":["刀箭傷的是兩族的孩子，不如收弓，讓牧草重新長回來。","我不貪你的土地，你也別貪我的，草原夠寬，容得下兩族。"],"accept":["好，對著太陽起誓，馬薩革泰人的話說出口就不收回。","弓收回箭囊，帳中生火煮肉，今日起你是草原的朋友。"],"reject":["你先奪我牧場，再談停戰？草原的風不會信這種話。","我的族人還沒忘記失去的帳篷，現在談和，太早了。"],"rebuff":["你拒絕了草原伸出的手，那就準備迎接草原射出的箭。","也罷，我已給過你機會，往後的日子，你要自己承擔。"],"betray":["你在停戰時偷牽我的馬群，誓約已被你踩碎，弓再度拉開。","太陽神看見了你的貪心，草原今日收回它的和平。"],"truceEnd":["休戰的日子到頭了，馬兒養肥了，弓弦也上好了。","和平的風停了，草原上的每一匹馬都在等我一聲令下。"],"attacking":["馬薩革泰的騎兵出發了，草原的馬蹄聲，就是我的戰鼓。","聽，地在震動，那是我族人的萬馬，正朝你的城奔去。"],"attacked":["帳篷燒了可以再搭，只要族人還在馬背上，草原就不會倒下。","你打到我的營地了，但草原女王不會跪，弓還在我手裡。"],"defeated":["我的族人會騎向更遠的草原，風會記得托米麗絲的名字。","弓斷了，馬倒了，但這片土地永遠不屬於征服者。"],"victory":["你也和波斯王一樣，敗在草原女王的弓下。","回去告訴你的子孫，馬薩革泰的土地，誰也拿不走。"],"allyAccept":["好，從今天起，我的弓手就是你的弓手，我的草原也護你。","兩族並肩，比一族單騎走得更遠，太陽神保佑我們的盟約。"],"allyReject":["草原人只跟守信的人結盟，你的話，我還信不過。","馬薩革泰的箭只為自己的族人而射，恕我不能與你同行。"]}},{"name":"弗拉基米爾大公","title":"基輔羅斯大公","era":"10 世紀末","tone":"剛毅果決的羅斯大公，帶著新皈依者的虔誠與戰士的豪氣。","portrait":"ru-historical-age1","lines":{"intro":["吾乃基輔的羅斯大公弗拉基米爾，聶伯河兩岸皆聽本公號令。","遠方的君主，羅斯的大門敞開，是友是敵，由你自己選。"],"contact":["你的人看見的是基輔，聶伯河畔的木牆與教堂，羅斯的心臟。","河上的商船載著毛皮與蜂蜜，來自各地的人都在此交易。"],"war":["本公的親兵已披甲上馬，羅斯的劍今日指向你。","你屢次侵擾我的邊境，如今由本公親自來討回公道。"],"warReply":["佩切涅格人也曾以為羅斯好欺，他們在我的邊牆前退回去了。","你想開戰？好，聶伯河的水會告訴你羅斯戰士的勇氣。"],"peace":["羅斯已受洗，本公願放下劍，以十字架之名與你言和。","刀劍換不來豐收，不如停戰，讓商船重回河上。"],"accept":["甚好，本公以十字架起誓，羅斯與你自此不動干戈。","你的誠意本公收下了，基輔的大門為朋友而開。"],"reject":["你的使者話說得好聽，但你的軍隊還在我的邊境上。","本公不與口是心非之人講和，回去吧。"],"rebuff":["本公伸出的手被你拒絕，那羅斯的劍就替本公說話。","也罷，你既不要和平，就別怪羅斯的親兵不留情面。"],"betray":["你在停戰期間收買我的封臣，這盟約已被你自己撕毀。","本公曾以為你是可信之人，是本公錯了，親兵，備馬！"],"truceEnd":["休戰的日子過去了，羅斯的親兵磨亮了劍，等本公一聲令下。","和平的鐘聲停了，聶伯河兩岸的戰士都已集結。"],"attacking":["羅斯的長船順河而下，本公親率親兵，直取你的城。","瓦良格人與斯拉夫人並肩出征，你的城牆擋不住這支軍隊。"],"attacked":["基輔的木牆燒了，但十字架仍立在山丘上，羅斯不會就此消失。","你打到了聶伯河畔，本公的親兵仍死守最後一道門。"],"defeated":["本公倒下了，但羅斯的信仰已在這片土地上生根。","願上帝寬恕你，也寬恕本公未能守住的基輔。"],"victory":["羅斯的劍勝了，這是上帝與聶伯河共同的裁決。","回去吧，把羅斯大公的名字帶回你的國家。"],"allyAccept":["甚好，本公與你結盟，羅斯的親兵從此也為你而戰。","以十字架為證，基輔與你的國家自此互為兄弟。"],"allyReject":["本公的盟友必須信得過，你的名聲還未傳到基輔。","羅斯不需要這樣的盟約，本公的親兵足以守住河岸。"]}},{"name":"伊凡雷帝 伊凡四世","title":"俄羅斯沙皇","era":"16 世紀","tone":"威嚴多疑、動輒震怒的沙皇，自信君權天授，語氣充滿壓迫感。","portrait":"ru-historical-age2","lines":{"intro":["朕乃全俄羅斯的沙皇伊凡，君權來自上帝，不容任何人質疑。","異邦的君主，跪或不跪，你要想清楚再開口。"],"contact":["你的人看到的是莫斯科，克里姆林的城牆之內，只有朕說了算。","那座九塔並立的教堂，是朕為攻下喀山而建，看清楚了。"],"war":["朕的火槍隊已列陣，沙皇的怒火，今日燒向你的國土。","你膽敢藐視沙皇？喀山的下場，就是你的下場。"],"warReply":["向朕宣戰？連韃靼的汗國都臣服了，你算什麼。","好極了，朕正愁沒有敵人可以讓射擊軍練練手。"],"peace":["朕今日心情尚可，願給你一紙停戰，莫要辜負沙皇的仁慈。","利沃尼亞的戰事已耗費太多，朕暫且與你言和。"],"accept":["很好，沙皇的話就是法律，這份停戰朕會遵守。","朕接受了，但記住，是朕賜給你和平，不是你求來的。"],"reject":["停戰？朕不與背後藏刀的人談和，回你的宮廷去吧。","朕的怒火尚未平息，你的求和信，朕看都不看。"],"rebuff":["你竟敢拒絕沙皇？這份無禮，朕會記在心裡，加倍奉還。","也罷，朕給過你機會，往後莫怪朕手下無情。"],"betray":["朕的耳目報告，你暗中與朕的叛臣往來，盟約作廢！","賞由朕出，罰亦由朕出，這份停戰，朕現在收回。"],"truceEnd":["休戰期滿，射擊軍已在城下列隊，沙皇的耐心也用完了。","和平的日子結束了，朕等這一天等得太久。"],"attacking":["朕親率大軍出征，火砲與射擊軍為前鋒，你的城撐不了多久。","沙皇的大軍已經上路，你最好開始向上帝祈禱。"],"attacked":["克里姆林在震動，但朕仍坐在王座上，誰也別想讓朕低頭。","你打到莫斯科城下了？朕的怒火，比你的火砲更可怕。"],"defeated":["連沙皇也有今日……上帝啊，這就是祢給朕的裁決嗎。","朕以雷霆治國，卻敗在你手裡，這頂王冠，你拿去吧。"],"victory":["這就是違抗沙皇的下場，全世界都該記住伊凡的名字。","莫斯科是第三羅馬，朕的權力來自上帝，你怎麼可能贏。"],"allyAccept":["朕准了，但這是沙皇的恩賜，你最好懂得感恩。","好，朕與你結盟，從此你的敵人也是沙皇的敵人。"],"allyReject":["沙皇不需要盟友，只需要臣民，你想當哪一種？","朕連自己的貴族都信不過，怎會信一個外邦人。"]}},{"name":"彼得大帝","title":"俄羅斯皇帝","era":"17 世紀末～18 世紀初","tone":"精力旺盛、務實直率的改革者，痴迷造船與軍事，急躁而豪邁。","portrait":"ru-historical-age3","lines":{"intro":["朕是俄羅斯的彼得，朕曾親手造船，也親手打仗，你呢？","朕是學生，向天下求師，你若有真本事，朕便向你討教。"],"contact":["你的人看見的是聖彼得堡，朕在涅瓦河沼澤上親手立起的新都。","看見港口裡的船了嗎？那是俄羅斯的第一支艦隊，朕的驕傲。"],"war":["朕的新軍已練成，火砲已上船，俄羅斯今日向你宣戰。","你擋在俄羅斯通往大海的路上，那朕只好把你搬開。"],"warReply":["瑞典的查理也向朕挑戰過，波爾塔瓦的原野還記得結果。","宣戰？好，朕在納爾瓦吃過敗仗，早就學會怎麼贏回來。"],"peace":["打仗花的錢夠造十艘船，不如停戰，朕還有整個國家要改造。","朕不想再耗下去，簽個停戰吧，朕的造船廠等著朕回去。"],"accept":["成交，朕說話算話，就像朕的船，造了就下水。","好，停戰。省下的軍費，朕全拿去造船和辦學校。"],"reject":["現在談停戰？你的艦隊還在朕的海岸外晃，先撤了再說。","朕不要一紙空文的和平，朕要的是通往海洋的出口。"],"rebuff":["你不要和平？也好，朕正好試試新鑄的火砲。","朕伸出手你不接，那就別怪俄羅斯的新軍不客氣。"],"betray":["你趁停戰在海上攔截朕的商船，這種和平，朕不要了。","朕忍夠了，停戰作廢，艦隊起錨，新軍出發！"],"truceEnd":["休戰期過了，朕的士兵這段時間沒閒著，天天操練。","和平的日子夠朕造好一支艦隊了，現在，該它們出海了。"],"attacking":["朕親自帶隊，陸上是新軍，海上是艦隊，兩路一起來。","士兵們，這一戰不是為了彼得，是為了俄羅斯，前進！"],"attacked":["聖彼得堡被圍了？這座城是朕從沼澤裡蓋起來的，不會倒。","你打到涅瓦河口了，但朕的船還在，俄羅斯就還有明天。"],"defeated":["朕想把俄羅斯帶向海洋……可惜，船還沒造完。","朕輸了，但俄羅斯已經睜開眼睛看見世界，這一點你改不了。"],"victory":["這就是新俄羅斯的力量，你打的是三十年前的老俄羅斯。","俄羅斯終於走向大海，而你，成了朕航道上的第一塊礁石。"],"allyAccept":["好，結盟！派你的工匠來朕的造船廠，朕派軍官去你那裡。","朕喜歡實在的朋友，你的艦隊加上朕的，海上誰敢攔。"],"allyReject":["朕的盟友要能打仗、會造船，你的國家還差一點。","現在不行，朕的軍隊還在改造，等朕準備好再說。"]}}],"de":[{"name":"阿米尼烏斯","title":"切魯西部族首領","era":"1 世紀（條頓堡森林之戰）","tone":"森林戰士的沉穩與警醒，守護族人與自由，對羅馬式的傲慢了然於心。","portrait":"de-historical-age0","lines":{"intro":["我是切魯西的阿米尼烏斯，森林的每棵樹都認得我。","異邦的君主，別把我的族人當成你的奴隸。"],"contact":["你的斥候踏進了我們的林地，這裡不是羅馬人的行省。","看見了吧，我們的村落沒有城牆，但有整片森林守著。"],"war":["你的傲慢和瓦盧斯一樣，那就一樣在森林裡結束吧。","各部族已在祖靈面前立誓，切魯西的長矛指向你。"],"warReply":["我在羅馬軍中學過他們的打法，你的軍隊嚇不倒我。","要來就來，森林裡的路，只有我們的族人認得。"],"peace":["我不為征服而戰，只為族人的自由，願與你停戰。","收起武器吧，秋收將至，我的族人需要回田裡。"],"accept":["好，森林與你之間，從今日起有了和平。","我以部族之名應允，切魯西人說話算話。"],"reject":["羅馬人也曾談和平，然後徵稅、奪地，我不再相信。","你的和平帶著枷鎖的味道，森林不會接受。"],"rebuff":["你拒絕了，那麼森林會替我回答你。","我伸出的手被推開了，族人們，準備長矛。"],"betray":["我曾為羅馬效力，也曾背離羅馬，這次輪到你了。","和約是你的東西，森林只認得自由，我們再戰。"],"truceEnd":["冬雪化了，林間的路乾了，該讓你見識切魯西的勇士。","休戰的日子到頭了，各部族的號角已在林中響起。"],"attacking":["戰士們已穿過森林，你的城牆擋不住熟悉地形的人。","我們從林間出發了，這一次，換你的土地聽見號角。"],"attacked":["村落燃起了煙，但只要森林還在，族人就不會屈服。","你打到了我的家園，可是你抓不住風，也抓不住我們。"],"defeated":["我為自由而戰，也為自由倒下，森林會記得我。","羅馬沒能做到的事，你做到了，但族人的火不會熄。"],"victory":["回去告訴你的人民，森林之外的野心到此為止。","你輸給的不是我，是這片土地和守護它的人。"],"allyAccept":["好，切魯西人與你並肩，森林裡多一個朋友。","各部族能聯手擊退羅馬，我們也能與你同行。"],"allyReject":["我聯合各部族是為了自由，不是為了替你打仗。","森林的盟約只給值得信任的人，你還不是。"]}},{"name":"腓特烈一世 巴巴羅薩","title":"神聖羅馬帝國皇帝","era":"12 世紀","tone":"帝王威嚴與騎士豪情並存，言必稱上帝與帝國榮耀。","portrait":"de-historical-age1","lines":{"intro":["朕乃羅馬人的皇帝腓特烈，上帝所立，萬王之首。","紅鬍子的名號傳遍歐陸，願你我以榮譽相待。"],"contact":["你的城池不錯，若肯向帝國稱臣，朕會保你平安。","朕的使者見過你的城牆，比米蘭的矮了些。"],"war":["帝國的榮耀不容輕慢，朕的騎士將越過阿爾卑斯山。","朕以上帝與帝國之名向你宣戰，願你的城牆夠堅固。"],"warReply":["敢向皇帝挑戰？米蘭的下場，你該聽說過。","很好，朕正嫌鎧甲久未上身，就讓你來磨亮它。"],"peace":["朕在康斯坦茨也曾與敵人握手，今日願與你言和。","聖地尚待朕去收復，你我之間，不如先罷兵。"],"accept":["朕應允了，皇帝的話一出口，就是帝國的法。","以王冠起誓，這份和約，朕會如騎士般守信。"],"reject":["你還沒資格與皇帝談條件，先打贏一場再說。","朕曾兩度圍攻米蘭，區區停戰，豈能動搖朕心。"],"rebuff":["你拒絕了皇帝的好意？這份傲慢，朕記下了。","也罷，朕的騎士本就不擅長等待和平。"],"betray":["和約已盡其用，帝國的榮耀高於一紙羊皮。","時勢已變，朕收回承諾，戰旗再度升起。"],"truceEnd":["休戰期滿，朕的軍隊已在阿爾卑斯山口集結。","和平的鐘聲停了，接下來響起的，是帝國的號角。"],"attacking":["朕親率大軍前來，紅鬍子的旗幟已在你的地平線上。","德意志的騎士已翻過山嶺，準備迎接皇帝吧。"],"attacked":["城牆在搖晃，但皇帝的王冠還戴在朕的頭上。","萊尼亞諾的敗仗朕都撐過來了，這一次也一樣。"],"defeated":["帝國的榮耀……朕沒能守住，願上帝寬恕。","紅鬍子倒下了，但皇帝的王冠，總會有人再戴上。"],"victory":["跪下吧，如今你也是帝國的一部分了。","上帝站在皇帝這邊，這場勝利便是明證。"],"allyAccept":["朕接受，願你我的旗幟並肩，共赴聖地。","與皇帝結盟，是你的榮幸，也是帝國的助力。"],"allyReject":["皇帝不需要盟友，只需要臣屬，你願意嗎？","朕的盟友已夠多了，多一個你，帝國並不會更強。"]}},{"name":"腓特烈大帝","title":"普魯士國王","era":"18 世紀","tone":"理性冷靜、帶點哲人式的嘲諷，軍事上自信，自稱國家第一公僕。","portrait":"de-historical-age2","lines":{"intro":["朕是普魯士的腓特烈，國家的第一公僕，幸會。","無憂宮的長笛尚未吹完，希望你不會太快打擾朕。"],"contact":["你的城看來富庶，希望你的軍隊操練得一樣勤快。","朕的斥候說你的城牆不錯，可惜城牆不會行軍。"],"war":["外交已無話可說，接下來由朕的擲彈兵替朕發言。","朕不愛戰爭，但普魯士的利益需要它，宣戰。"],"warReply":["向朕宣戰？奧地利、法蘭西、俄羅斯都試過了。","好極了，朕正想試試新的斜線陣，感謝你的配合。"],"peace":["戰爭花的是國庫的錢，朕算過了，停戰比較划算。","打了這麼久，你我都該回去讀點書了，停戰吧。"],"accept":["成交，朕會把和約放在伏爾泰的信旁邊，好好保存。","理性的選擇，朕欣賞理性的人，和平生效。"],"reject":["此刻談和平？西里西亞還沒到手時朕也沒停過。","你的條件朕看過了，寫得不錯，可惜對普魯士無益。"],"rebuff":["拒絕了？可惜，朕本以為你比你的將軍們聰明。","也好，談判桌上得不到的，戰場上朕會自己拿。"],"betray":["條約是用來服務國家的，如今它沒用了，朕撕了。","別怪朕，君主的第一美德是替國家著想，開戰。"],"truceEnd":["休戰結束，長笛收起來了，該換軍鼓上場。","和平的時限到了，普魯士的軍隊從不遲到。"],"attacking":["朕的軍隊已經出發，行軍速度會讓你來不及準備。","擲彈兵已列隊前進，朕就在隊伍前頭，等你出來。"],"attacked":["柏林被圍過，朕也撐過來了，奇蹟總在最後出現。","城牆會塌，但朕還握著劍，普魯士就還沒輸。"],"defeated":["朕盡了公僕的職責，普魯士，朕沒能再守住你。","棋局結束了，你贏得漂亮，朕輸得不算難看。"],"victory":["勝負已定，朕要回無憂宮吹笛了，你請自便。","這就是紀律與理性的勝利，希望你學到了什麼。"],"allyAccept":["結盟可以，但朕提醒你，普魯士的盟友得跟上腳步。","很好，朕正需要一個能在地圖上一起看棋的朋友。"],"allyReject":["盟約對普魯士無益，朕不簽沒有用處的紙。","你的友誼朕領了，但你的軍隊，朕暫時不需要。"]}},{"name":"俾斯麥","title":"德意志帝國首相","era":"19 世紀","tone":"務實冷硬、算計精準，鐵血作風中帶著老練的外交幽默。","portrait":"de-historical-age3","lines":{"intro":["本相俾斯麥，代德意志皇帝向你問候，請坐下談。","重大的問題不靠演說，靠鐵與血，記住這句話。"],"contact":["你的城不錯，本相已經在計算它在地圖上的價值。","德意志的鐵路修到哪裡，帝國的目光就看到哪裡。"],"war":["外交的手段用盡了，本相只好換一種語言跟你談。","帝國的利益需要這場戰爭，本相從不做多餘的事。"],"warReply":["你宣戰了？很好，本相省下了寫電報的工夫。","丹麥、奧地利、法蘭西都跟普魯士交過手，結果你知道的。"],"peace":["戰爭是手段，不是目的，目的達成了，該談和了。","本相不喜歡多打一天沒有用的仗，我們談條件吧。"],"accept":["成交。本相會把條款寫得清楚，免得你日後誤會。","明智的決定，歐洲的棋盤上，又少了一個亂子。"],"reject":["現在停戰？你的籌碼還不夠，本相不做賠本生意。","條件本相看過了，帝國得不到好處的和平，不如不談。"],"rebuff":["你拒絕了？沒關係，本相手上還有別的牌。","拒絕一位老外交官的提議，你會付出比想像更多的代價。"],"betray":["條約是為當時的局勢寫的，局勢變了，條約自然失效。","本相說過，政治是可能性的藝術，現在的可能是開戰。"],"truceEnd":["休戰期滿，本相已算好了，帝國的軍隊準備就緒。","和平的緩衝期過去了，接下來每一步都要精打細算。"],"attacking":["帝國的軍隊已搭上火車出發，比你的信使快得多。","毛奇將軍已經動身，本相只負責告訴你這個消息。"],"attacked":["柏林告急，但本相還在辦公桌前，帝國就還沒倒。","你打到了皇宮門口，可惜本相的電報線還沒斷。"],"defeated":["本相一生為帝國盤算，這一局，是本相算錯了。","歐洲的棋盤少了一個棋手，希望你下得比本相好。"],"victory":["結果和本相計算的一樣，帝國不需要意外。","棋局結束，你輸在看不清局勢，不在兵力。"],"allyAccept":["同盟可以簽，本相會讓條款對雙方都有好處。","很好，本相一向相信盟友比敵人省事得多。"],"allyReject":["帝國的盟約簽得夠多了，本相不想再多養一個負擔。","你的位置在棋盤上不夠關鍵，本相暫時不需要你。"]}}],"cn":[{"name":"秦始皇 嬴政","title":"秦朝皇帝","era":"上古（秦漢 前221–220）","tone":"威嚴冷峻、法家口吻，以一統天下為傲，視天下為己有","portrait":"cn-historical-age0","lines":{"intro":["六國既滅，四海為一。朕乃始皇帝，爾等小邦何足道哉。","朕掃平六國，一統天下。爾若識時務，便早早稱臣。"],"contact":["咸陽城牆高聳，馳道直通四方，爾等可曾見過如此氣象？","此乃大秦都城咸陽，法令森嚴，外人不得妄動。"],"war":["六國已滅，爾亦難逃。大秦鐵騎即刻出征。","朕欲書同文、車同軌，爾國豈可自外於天下？出兵！"],"warReply":["區區小國竟敢挑釁大秦？蒙恬何在，替朕教訓此人。","六國聯軍尚且敗於朕手，爾一國之力，能奈朕何？"],"peace":["北有匈奴未平，朕暫無暇顧爾。且休兵，各守疆界。","長城尚未築成，朕願與爾暫止干戈，各自經營。"],"accept":["好，朕准了。然法令如山，爾若毀約，必受重懲。","既然爾有誠意，朕便應允。天下事，暫且如此。"],"reject":["朕志在一統，豈容天下有第二個君王？休想停戰。","當年六國也曾求和，結果如何？朕不會再聽這種話。"],"rebuff":["爾竟拒絕朕的好意？也罷，秦法無情，後果自負。","朕難得開口言和，爾卻不識抬舉。且看爾能撐多久。"],"betray":["朕說過，天下只能有一個皇帝。停戰到此為止。","北疆已定，長城已成，朕的大軍如今無後顧之憂。"],"truceEnd":["休戰之期已滿。天下大勢，自今日起由朕來定。","刀兵可以出鞘了。爾等好自為之，莫怪朕不留情面。"],"attacking":["大秦鐵騎已出函谷關，爾的城池，朕勢在必得。","朕親率大軍前來，爾若開城歸降，朕可饒爾一回。"],"attacked":["咸陽竟被兵臨城下？朕統一天下，豈能敗於此地！","城牆將傾……不，朕是始皇帝，秦當傳至萬世！"],"defeated":["朕本欲傳之萬世……大秦，竟止於朕一人之手。","六國之仇，今日償還了。天下……終究非朕一人所有。"],"victory":["六國既滅，四海為一。今日之後，天下再無他國。","書同文，車同軌，爾的土地自此併入大秦郡縣。"],"allyAccept":["朕破例與爾結盟。記住，秦的盟約不可輕忽。","遠交近攻，本是秦策。既如此，朕便與爾聯手。"],"allyReject":["朕從不與人共享天下。結盟？免談。","大秦自有蒙恬、王翦，何須外人相助？"]}},{"name":"唐太宗 李世民","title":"唐朝皇帝","era":"中古（唐宋 618–1279）","tone":"雄才大略卻寬仁納諫，以民為本，先禮後兵","portrait":"cn-historical-age1","lines":{"intro":["朕乃大唐天子，四方尊為天可汗。爾若來歸，朕以禮相待。","貞觀之世，四海昇平。閣下遠來，是為友，還是為敵？"],"contact":["長安城百業興盛，各國商旅雲集，此乃大唐氣象。","爾的使者既到長安，便當知大唐之富庶與寬仁。"],"war":["朕以仁待人，然爾屢犯邊境，大唐不得不出兵了。","頡利可汗尚且敗於李靖之手，爾何足懼？大唐出兵！"],"warReply":["爾竟向大唐宣戰？朕本不願用兵，既如此，便應戰。","突厥、吐谷渾皆已臣服，爾之挑釁，朕自當回應。"],"peace":["兵者凶器，聖人不得已而用之。朕願與爾罷兵休戰。","百姓方安，朕不欲再興戰事。爾若願意，兩國息兵吧。"],"accept":["善。朕素以和為貴，自今日起，兩國互不相犯。","爾有此心，朕甚欣慰。願天下少一分兵戈。"],"reject":["爾言和之時，兵馬卻未退，朕如何信爾？此議不允。","朕納諫如流，卻不受人蒙蔽。停戰之議，暫且擱下。"],"rebuff":["爾拒絕了朕的好意，可惜。那便沙場上見真章吧。","朕已仁至義盡。爾既不願休戰，大唐奉陪到底。"],"betray":["朕本欲守約，然爾暗中屯兵邊境，大唐不能坐視。","停戰已無意義，朕決意再度興兵，望爾莫怪。"],"truceEnd":["休戰之期已至。朕不主動生事，但也絕不畏戰。","各國兵馬皆已就緒。天下之勢，就看誰更得民心了。"],"attacking":["李靖已率大軍出發。爾若及早歸降，朕必善待爾民。","唐軍此去，只為止戰，不為劫掠。爾好自為之。"],"attacked":["長安危急？朕曾平定天下，今日豈能失於此城！","水能載舟，亦能覆舟。莫非朕已失了民心？"],"defeated":["以史為鏡，可知興替。朕的貞觀，也到了盡頭。","願爾善待大唐百姓。這是朕最後的請求。"],"victory":["天下歸唐，四海一家。爾的子民，朕自會善待。","貞觀仁政，今日終及於爾土。放下兵器，共享太平吧。"],"allyAccept":["大唐願與爾結為兄弟之邦，互通有無，共禦外敵。","善。朕以誠待人，望爾亦以誠相報。"],"allyReject":["結盟之事，朕與群臣商議後，認為時機未到。","魏徵勸朕勿輕許盟約。爾之誠意，朕仍需觀察。"]}},{"name":"明太祖 朱元璋","title":"明朝皇帝","era":"近世（元明 1271–1644）","tone":"布衣天子、直白務實又多疑，護百姓卻嚴厲不留情","portrait":"cn-historical-age2","lines":{"intro":["朕本淮右布衣，起於草莽，今為天下之主。爾是何人？","朕推翻元朝，恢復中華。爾若安分守己，朕不為難。"],"contact":["應天府城牆高厚，乃朕高築牆、廣積糧所成。","此城守衛森嚴，爾的人在城外看看便好，莫要靠近。"],"war":["朕平陳友諒、滅張士誠，何懼爾一國？徐達，出兵！","爾屢屢擾朕邊民，朕忍無可忍。大明鐵騎，即刻出征。"],"warReply":["爾竟敢向大明宣戰？朕從一介布衣打下江山，不怕爾。","好，朕正愁沒有藉口。徐達、常遇春，隨朕迎敵！"],"peace":["百姓剛從戰亂中喘息，朕不願再動干戈。且休兵吧。","朕要百姓種田納糧，不要他們打仗。爾我暫且停戰。"],"accept":["好，朕答應。但朕最恨背信之人，爾莫要試探朕。","既然爾有誠意，朕便收兵。各安其土，各養其民。"],"reject":["爾嘴上求和，暗地裡卻在整軍，當朕看不出來？不准。","朕多疑，這天下人皆知。爾的和議，朕信不過。"],"rebuff":["朕難得好言相勸，爾卻不領情。好，那就打到底。","不識抬舉！朕從乞食僧到皇帝，什麼硬仗沒打過？"],"betray":["朕查得爾私通朕的臣子，此等停戰，不要也罷！","停戰之約，朕撕了。天下事，終究得靠刀劍說話。"],"truceEnd":["休戰結束了。朕的糧倉已滿，兵馬已足，不怕誰來。","高築牆、廣積糧的日子過去了，如今該爭天下了。"],"attacking":["大明之師已出應天。爾若識相，早早開城，免傷百姓。","徐達領兵，朕親自督戰。爾的城池，守不了幾日。"],"attacked":["應天告急？朕在鄱陽湖險些喪命都撐過來了，不會怕。","城牆築得再高，也擋不住爾嗎……眾將士，隨朕守城！"],"defeated":["朕從布衣起兵，如今又歸於塵土。天命，原來如此。","朕只求爾一事：讓百姓有田可種，有飯可吃。"],"victory":["推翻元朝，恢復中華，今日大明終於一統天下。","朕從一個牧童走到今日，爾輸給朕，不算冤枉。"],"allyAccept":["好，朕與爾結盟。但朕醜話說在前頭，背盟者，朕必追究。","爾既有誠意，朕便信爾一回。兩國互市，共保太平。"],"allyReject":["朕連丞相都廢了，還會把國事交給外人？免了。","結盟？朕信不過爾。大明自有徐達、湯和，不需外援。"]}},{"name":"康熙帝 玄燁","title":"清朝皇帝","era":"近代（清 1644–1912）","tone":"博學勤政、沉穩寬仁，以文治為傲，先禮後兵","portrait":"cn-historical-age3","lines":{"intro":["朕乃大清天子。滿漢一體，四海皆朕子民，爾何來？","朕八歲登基，親政以來平三藩、定臺海。閣下有何指教？"],"contact":["紫禁城巍峨，八旗駐守四門。爾的人可看清楚了？","京城之內，觀象臺有西洋儀器，朕正學習測算天象。"],"war":["朕三次親征噶爾丹，不畏遠征。今日，輪到爾了。","羅剎犯邊，朕尚且以兵驅之。爾之挑釁，朕豈能容？"],"warReply":["爾向大清宣戰？三藩之亂朕尚能平定，何況爾一國。","朕本欲以文治天下，爾既動兵，朕便以八旗相迎。"],"peace":["尼布楚之約可與羅剎立，與爾亦可。兩國劃界，各守其疆。","連年用兵，百姓困苦。朕願與爾罷兵，休養生息。"],"accept":["好。朕以誠信立國，既然約定，大清必守。","爾能明白止戰之理，甚好。願兩國從此各享太平。"],"reject":["吳三桂當年也曾請和，朕不曾答應。爾亦如此。","爾邊境兵馬未撤，此時言和，朕難以相信。"],"rebuff":["爾拒絕了朕的好意，也罷。大清從不強人所難，戰場上見。","朕已給爾機會。既然爾執意如此，朕便不再多言。"],"betray":["朕本以誠相待，然爾暗中結黨對付大清，約定作廢。","撤藩之時朕便學到：有些禍患，不能留到明日。出兵。"],"truceEnd":["休戰之期已滿。朕已備妥糧草，不懼任何挑戰。","天下棋局已開。朕讀過歷代興亡，知道該怎麼走。"],"attacking":["八旗與綠營已出京師。爾若開城歸順，朕保爾百姓無恙。","朕親征噶爾丹尚且不辭辛勞，此番親自督軍，爾當心了。"],"attacked":["京師危急？朕八歲登基，什麼風浪沒見過，守住！","紫禁城牆將破……朕勤政數十年，難道要敗於今日？"],"defeated":["朕一生勤學勤政，大清竟終於朕手。歷史，自會評斷。","願爾永不加賦，善待百姓。這是朕最後的囑託。"],"victory":["天下歸清，滿漢一家。爾之子民，朕視同己出。","自今日起，爾土納入大清版圖。朕以文治之，不以兵壓之。"],"allyAccept":["好，大清願與爾結盟。互通商貿，共禦外患。","朕重信義。既結盟約，大清必不負爾。"],"allyReject":["結盟之事，朕需與議政王大臣商議，此時不便應允。","朕觀爾行事，尚難放心。結盟之議，容後再說。"]}}],"gb":[{"name":"布狄卡","title":"愛西尼部族女王","era":"羅馬不列顛（1 世紀）","tone":"守護族人與土地的部族女王，語氣剛烈而有尊嚴，把自由看得比王座更重。","portrait":"gb-historical-age0","lines":{"intro":["吾是愛西尼的布狄卡，這片土地由祖靈所託，不容外人踐踏。","陌生的王，橡樹林記得每一位來客，是友是敵，由你自己選。"],"contact":["你的斥候已站在吾族的田野上，愛西尼人看見了，也記住了。","這裡沒有石牆高塔，只有守著家園的族人，別小看他們。"],"war":["你們的貪婪已越過河流，愛西尼的戰車今日為自由而出。","吾不為王座而戰，只為被奪走的自由而戰。準備迎接長矛吧。"],"warReply":["你選擇了戰爭？很好，部族的長矛從不畏懼任何旗幟。","來吧，讓你的士兵見識不列顛的女人如何守護家園。"],"peace":["族人需要秋收，你的人也需要歸鄉。放下武器，各守其土如何？","吾不愛戰爭，只愛族人平安。若你願意停手，吾也願意。"],"accept":["好，祖靈為證，愛西尼人說出口的話，不會收回。","橡樹林將記下今日的誓言，願兩地的孩子都能安穩長大。"],"reject":["奪走的土地還沒歸還，吾怎能對族人說已經和平？","你的話像河上的霧，看似溫柔卻藏著刀。吾不接受。"],"rebuff":["你拒絕了？那就讓大地見證，誰才真心為子民著想。","吾伸出的手被推開了，下一次伸出的，會是長矛。"],"betray":["停戰期間你的人仍在侵佔田地，誓言已被你踏碎，吾不再忍讓。","祖靈看見了你的背信。愛西尼的戰車再度啟程，這次不回頭。"],"truceEnd":["休戰的日子結束了，族人已磨好長矛，就看你要走哪條路。","和平的時光很短，但吾記得每一天。現在，各憑本事了。"],"attacking":["戰車已駛出橡樹林，部族的號角響遍原野，吾親自領軍而來。","聽見馬蹄聲了嗎？那是愛西尼人為家園討回公道的聲音。"],"attacked":["土牆可以倒下，但愛西尼人的心不會。族人們，守住最後一寸土！","你打到吾的家門口了，可祖靈仍在，吾就仍站在這裡。"],"defeated":["吾寧可倒在自己的土地上，也不做他人的奴僕。族人，記住自由。","長矛折了，戰車停了，但這片土地永遠記得愛西尼的名字。"],"victory":["大地重歸族人，你的旗幟將從此離開這片原野。","吾為自由而戰，如今自由回來了。回去吧，別再踏上這裡。"],"allyAccept":["好，愛西尼與你的族人結為兄弟，共守這片原野與河流。","同飲一條河的水，就是一家人。吾接受這份盟約。"],"allyReject":["愛西尼人只與真心相待者結盟，你的誠意，吾還沒看見。","族人的命運不能交給陌生人。今日不結盟，但也不必為敵。"]}},{"name":"獅心王 理查一世","title":"英格蘭國王","era":"12 世紀","tone":"好戰直率的騎士國王，把榮譽與戰場看得比王宮更重，語氣豪邁帶著獅子的傲氣。","portrait":"gb-historical-age1","lines":{"intro":["本王是理查，人稱獅心。與其在王宮枯坐，本王更愛馬背與戰場。","見到獅子紋章了嗎？記住它，戰場上你會再見到它。"],"contact":["你的人到了本王城下？看仔細些，這裡每塊石頭都準備好打仗。","城牆上的獅子旗迎風招展，那是英格蘭的驕傲，別靠太近。"],"war":["本王的長劍生鏽太久了，今日對你宣戰，正好磨一磨。","上帝與吾之權利！騎士們，上馬，隨本王出征！"],"warReply":["你向獅子宣戰？好膽量。本王就喜歡不怕死的對手。","正合本王心意。備馬，讓對方看看十字軍的鎖子甲有多硬。"],"peace":["打了這麼久，你的勇氣本王看見了。不如暫且收兵，各自養精蓄銳。","本王在聖地也曾與敵手握手言和，今日對你亦然，停戰吧。"],"accept":["成交！騎士一諾千金，本王的劍在停戰期間不會出鞘。","好，本王答應。值得尊敬的對手，比朝廷裡的臣子有趣多了。"],"reject":["現在談和？獅子還沒吼夠，本王的騎士也還沒盡興。","本王從不在佔上風時放下劍，等你贏一場再來說。"],"rebuff":["拒絕了？也好，本王本來就更擅長用劍說話。","你不要和平，那就要戰爭。獅心王向來給人他要的東西。"],"betray":["你在停戰期間招兵買馬，本王看在眼裡。誓約作廢，開戰！","和平的日子讓劍鏽了，而你先背了誓。本王撕毀盟約，披甲上馬！"],"truceEnd":["休戰期滿了，總算能痛快打一場。騎士們，把馬牽來！","等這一天等得本王骨頭發癢。現在，讓刀劍決定一切。"],"attacking":["獅子的旗幟已越過邊境，本王親自衝在最前面，迎戰吧！","本王從不躲在後方指揮，這次也一樣。看見那面獅旗了嗎？"],"attacked":["城牆破了又如何？獅子受傷時更兇猛，本王仍握著劍。","本王曾在異鄉被囚仍不低頭，這座城，也不會輕易交出。"],"defeated":["劍已斷，馬已倒，但本王是站著倒下的。這就是獅心。","本王一生都在戰場，能終於戰場，也算不辱獅子之名。"],"victory":["勝負已分。你打得不錯，本王記住你的名字了，退下吧。","獅子吼過了，戰場歸於寂靜。這場勝利，獻給英格蘭。"],"allyAccept":["好，並肩作戰的兄弟！下次出征，你的旗幟就在本王身旁。","本王欣賞勇者。從今起，獅子與你同進退，這是騎士的誓言。"],"allyReject":["結盟？本王的劍不需要別人的手來扶，自己打就夠了。","獅子不與羊群結伴。等你證明自己是頭獅子，再來談。"]}},{"name":"伊莉莎白一世","title":"英格蘭女王","era":"16 世紀","tone":"機敏優雅、綿裡藏針的女王，字字得體卻句句有算計，以英格蘭為夫、以海洋為疆。","portrait":"gb-historical-age2","lines":{"intro":["朕是伊莉莎白，英格蘭的女王。朕已嫁給這個國家，無暇他顧。","歡迎來到朕的宮廷。朕看得多、說得少，你的心思，朕都明白。"],"contact":["你的使者已望見倫敦塔了？請轉告他，朕的海軍比城牆更高。","泰晤士河邊的城，是靠智慧而非高牆守住的。看清楚再走。"],"war":["朕給過你機會。如今英格蘭的艦隊揚帆，這是朕的答覆。","朕雖是女子之身，卻有國王的心與膽。宣戰吧，朕不會退。"],"warReply":["你向英格蘭宣戰？朕收下了。海上的風，一向站在朕這邊。","很好，朕正想看看你的船能不能越過海峽。德瑞克，出航。"],"peace":["戰爭耗盡國庫，也耗盡民心。朕提議停戰，貿易勝過砲火。","聰明的君主知道何時收劍。朕願暫且和談，你呢？"],"accept":["朕接受。英格蘭的信用如同金幣，落地有聲，絕不摻假。","好，朕以女王之名應允。願兩國的商船從此比戰船更多。"],"reject":["和談？你的條件像戴著珠寶的空盒子，好看而已。朕不要。","朕看得見你藏在笑容後的算計。這份和約，朕暫不簽。"],"rebuff":["你拒絕了朕的好意？無妨，朕向來擅長等待，也擅長記帳。","可惜。朕伸出的是橄欖枝，你卻當成了荊棘。"],"betray":["停戰期間你暗中結黨，朕的耳目一清二楚。和約作廢，開戰。","朕說過朕看得多、說得少。現在，朕要開口了：戰爭。"],"truceEnd":["休戰期已盡，棋局重開。朕的每一步，都已算好了。","和平的帷幕落下了。接下來，讓英格蘭的艦隊替朕說話。"],"attacking":["朕的艦隊已出港，風帆遮天。這不是威嚇，是通知。","英格蘭的大軍已在路上。朕親自到岸邊送行，他們不會空手回來。"],"attacked":["城門將破，朕仍戴著王冠。英格蘭的女王，從不躲在後方。","你打到宮門前了？朕就站在這裡，看看你敢不敢再進一步。"],"defeated":["朕的一生都獻給了英格蘭，如今無愧於她。王冠，朕親手放下。","潮水終有退去之時。記住，英格蘭曾有一位女王，未曾低頭。"],"victory":["勝負已定。回去告訴你的人民，英格蘭的女王，從不虛言。","風把你的艦隊吹散了，正如朕所料。海洋，是英格蘭的。"],"allyAccept":["朕接受結盟。你的船與朕的船並行，海上便無人能敵。","好，英格蘭與你攜手。朕的宮廷向你敞開，但秘密除外。"],"allyReject":["結盟？朕連求婚者都一一婉拒了，何況是你。","朕不輕易許諾。英格蘭的盟友很少，正因如此才珍貴。"]}},{"name":"維多利亞女王","title":"大英帝國女王","era":"19 世紀","tone":"端莊克制、不怒自威的帝國女王，字句簡短而有分量，以體面與秩序衡量一切。","portrait":"gb-historical-age3","lines":{"intro":["朕是維多利亞，日不落帝國的女王。願我們的往來，體面而有序。","朕的鐵路通向四方，朕的海軍守著七海。你，站在哪一邊？"],"contact":["你的人看見倫敦的煙囪了？那是工廠在運轉，也是帝國在呼吸。","請你的使節守規矩。朕的城市秩序井然，不容喧嘩。"],"war":["朕不喜歡戰爭，但更不喜歡無禮。帝國的艦隊，將替朕教你分寸。","朕的耐心已盡。首相已呈上文書，大英帝國正式對你宣戰。"],"warReply":["你竟向帝國宣戰？朕並不覺得有趣。海軍部，準備出航。","很好，這正好讓世界再次看見，太陽為何不落在帝國的旗上。"],"peace":["戰爭使商路中斷，朕的臣民不樂見。停戰吧，讓貿易重新流動。","朕願意談。體面的和平，比無止境的砲火更配得上兩個國家。"],"accept":["朕批准。條約將以帝國之名蓋印，朕的簽名從不作廢。","很好。願兩國的火車與商船，從此比軍隊更常來往。"],"reject":["朕讀過你的條件了。不，這樣的條件配不上帝國的體面。","和平需要誠意，你的提案裡朕沒有看見。請回去重擬。"],"rebuff":["你拒絕了？朕記下了。帝國的記性，向來很好。","朕以禮相待，你卻置之不理。那麼，就按帝國的方式來。"],"betray":["你在停戰期間騷擾帝國的商路，條約已無意義。朕宣布重啟戰事。","帝國的容忍有其界限，而你已越過。和約作廢，艦隊出港。"],"truceEnd":["休戰期結束了。朕已將此事交給海軍部，接下來由他們回答你。","和平的鐘聲停了。帝國的蒸汽船已升火，就等朕一聲令下。"],"attacking":["帝國的艦隊已駛出港口，鐵甲與蒸汽，將把朕的意志送到你門前。","朕的軍隊已出發。他們紀律嚴明，不會遲到。"],"attacked":["宮牆在震動，但朕不會摘下王冠。帝國的女王，坐著也能守城。","你打到白金漢宮門前了？朕仍在此。這身黑衣，不是為你而穿。"],"defeated":["太陽終究落下了。朕的帝國曾遍及四海，這一點，歷史不會忘。","帝國有起有落，朕已盡了女王的本分。請保持體面，朕也會。"],"victory":["戰事已了。帝國的旗幟將在你的城上升起，日不落，如往常。","朕並不以戰勝為樂，但秩序必須恢復。現在，它恢復了。"],"allyAccept":["朕同意結盟。帝國的商船與你的港口，從此互相敞開。","很好。朕的家族與歐洲各國王室皆有姻親，如今又多一位朋友。"],"allyReject":["結盟？帝國不需要盟友來證明強大。朕的答覆是：不。","朕欣賞你的誠意，但帝國的門檻很高。此事，容後再議。"]}}],"in":[{"name":"阿育王","title":"孔雀王朝君主","era":"孔雀王朝（前 3 世紀）","tone":"歷經羯陵伽之痛後以法治國的悔悟君王，語氣沉靜莊重，寧以法勝而非武勝。","portrait":"in-historical-age0","lines":{"intro":["朕乃天所親愛的喜見王阿育。願以法相待，不以刀兵。","孔雀王朝的石柱立於四方，願閣下也讀一讀朕的法敕。"],"contact":["你的人已見過華氏城了？城裡刻的不是戰功，是法。","那些石柱與象群並非炫耀，是提醒朕莫再重蹈羯陵伽。"],"war":["朕曾誓言不再興兵，然你威脅萬民安寧，朕不得不為。","為護百姓，孔雀的大軍將再度出征，朕心無喜悅。"],"warReply":["你選擇了刀兵。朕會應戰，但戰後仍願與你談法。","羯陵伽的教訓朕未曾忘，但朕的象兵也未曾老去。"],"peace":["刀兵所得，不及法勝之萬一。願與閣下止戰。","朕在羯陵伽見過十萬人的悲苦，不願再見。停戰吧。"],"accept":["善哉。放下刀劍的那一刻，你我皆得法之利益。","朕接受。願兩國邊界從此只往來商旅與僧侶。"],"reject":["朕愛好和平，卻不能在你兵臨城下時輕信諾言。","你的和議來得太急。先退兵，再談法與和平。"],"rebuff":["你拒絕了和平。朕不怒，只為兩國百姓感到惋惜。","無妨，法的種子未必今日發芽。朕會再提。"],"betray":["朕曾立誓守和，然你暗中屯兵邊境，誓約已被你毀。","法敕教朕寬容，卻不教朕縱容。孔雀再度出征。"],"truceEnd":["休戰之期已盡。朕仍願以法相交，但不懼刀兵。","和平的日子過去了。閣下欲取法，或取刀？"],"attacking":["象兵已渡河。朕不以此為榮，只求速戰速決。","孔雀的旗幟正朝你而來。願此戰是最後一戰。"],"attacked":["華氏城牆已裂。朕曾讓他人嘗此苦，今日輪到朕了。","城可破，法不可破。朕的石柱仍會站在原地。"],"defeated":["孔雀王朝到此為止。願法比朕活得更久遠。","朕輸了土地，但那些刻在石上的話，你抹不去。"],"victory":["戰事結束了。朕不慶功，只在你的城中立一根石柱。","你敗了，但朕不會奴役你的百姓。這是法的勝利。"],"allyAccept":["朕的使者曾遠赴諸國傳法，今日又多一位友邦。","善。願你我之邦如恆河與其支流，同流而不相爭。"],"allyReject":["朕不與好戰之人結盟。待你放下刀劍，再來談吧。","結盟為的是護民，不是征伐。朕暫且婉拒。"]}},{"name":"戒日王 曷利沙","title":"戒日王朝君主","era":"7 世紀","tone":"文武兼備的詩人君王，慷慨好客、崇佛尚學，語氣風雅自信，兼有征伐北印的豪氣。","portrait":"in-historical-age1","lines":{"intro":["本王曷利沙，統領五印度之北。閣下是來論詩，還是論戰？","曲女城的大門為賓客而開，也為敵人而閉。你是哪一種？"],"contact":["你的人到了曲女城？恆河邊的寺院與學堂，可不是擺設。","遠方來的僧人都說本王的城好客，願你的人也這麼覺得。"],"war":["本王曾為兄長之仇揮兵北印，今日為國之尊嚴向你宣戰。","筆可寫詩，也可寫戰書。本王的象軍已列陣待發。"],"warReply":["你向本王宣戰？好，戰場上見，本王會記下這一頁。","北印五國皆曾與本王交鋒，如今又添一個。來吧。"],"peace":["戰事擾了學堂的讀書聲。本王提議止戰，你意下如何？","五年一度的無遮大會將至，本王不願在此時動刀兵。"],"accept":["好，本王允了。今晚曲女城設宴，為兩國的和平添一首詩。","和平比勝利更難得。本王欣然接受。"],"reject":["你的和議來得太遲，戰鼓已響，本王不能半途收兵。","本王好客，但不天真。此時談和，恕難答應。"],"rebuff":["你拒絕了？可惜。本王的宴席與和議，不會永遠敞開。","也罷。詩人懂得等待，君王更懂。"],"betray":["本王本欲以禮相待，你卻在邊境築壘。和約作廢，開戰。","你當本王只會吟詩？和約已碎，象軍再出。"],"truceEnd":["休戰結束了。本王手中，此刻既有詩卷，也有長劍。","安穩的日子過去了，閣下要做本王的賓客，還是對手？"],"attacking":["本王親率象軍出征，曲女城的旗幟正朝你而去。","大軍已渡恆河。本王曾以此統一北印，今日再走一遭。"],"attacked":["曲女城危急了。學堂裡的經卷，請莫要毀去。","本王的城牆快撐不住了，但本王的筆還握在手裡。"],"defeated":["戒日王朝到此落幕。願後人記得本王的詩，多過本王的戰。","本王輸了。請善待曲女城的僧人與學子。"],"victory":["勝負已分。本王不取你的性命，只取這一頁史詩。","你敗了。本王將在大會上把財物散給百姓，包括你的。"],"allyAccept":["好！本王與你結盟。曲女城的大門，從此為你常開。","盟約已定。本王會為此寫一齣新戲，讓全城傳唱。"],"allyReject":["本王的盟友須知禮尚學。閣下，恕本王暫不結盟。","結盟之事，本王另有考量。今日就先當賓客吧。"]}},{"name":"阿克巴","title":"蒙兀兒皇帝","era":"蒙兀兒（16 世紀）","tone":"兼容並蓄的蒙兀兒大帝，語氣寬宏而自信，好辯論、重人才，戰場上亦果決不猶疑。","portrait":"in-historical-age2","lines":{"intro":["朕是阿克巴，蒙兀兒之主。宮中容得下各種信仰，也容得下你。","朕的辯論廳歡迎智者。閣下若只帶了刀，請留在門外。"],"contact":["你的人見到法泰普爾西克里了？那是朕以紅砂岩築的新都。","城裡有清真寺，也有印度教的廟。朕的臣民各拜各的神。"],"war":["朕給過你和平的機會。如今蒙兀兒的火砲與象軍將為朕開路。","朕十三歲登基，戰場是朕的第二個宮廷。向你宣戰。"],"warReply":["你向蒙兀兒宣戰？勇氣可嘉。朕會親自到陣前看看你。","很好。朕的將領正嫌太平日子無事可做。"],"peace":["刀劍能奪城，卻奪不了人心。朕提議停戰，你我各安其民。","朕與拉傑普特諸王能化敵為友，與你也可以。停戰吧。"],"accept":["好，朕接受。以寬容治天下，這是朕一貫的道理。","朕允了。願兩國的商隊在邊境相遇時，只談絲綢與香料。"],"reject":["朕寬容，但不是軟弱。此時求和，恕朕不能答應。","你的條件不夠誠意。回去想清楚，再派使者來。"],"rebuff":["你拒絕了朕的和平？無妨，朕的耐心比你的城牆更厚。","也好。辯論廳裡的智者說，固執的人得用時間說服。"],"betray":["和約之下，你竟暗中結黨圖謀朕的疆土。朕收回和平。","朕的寬容有底線，你已越過。蒙兀兒的大軍重新集結。"],"truceEnd":["休戰結束。朕的火砲已擦亮，但朕更希望它們不必開火。","太平的日子到頭了。閣下，是做朕的朋友，還是對手？"],"attacking":["蒙兀兒的象軍與火砲已經開拔。朕會親自騎象壓陣。","大軍出發了。朕從喀布爾到孟加拉都走過，你的城不遠。"],"attacked":["城門快守不住了。朕的九寶臣子仍在殿中，朕不會拋下他們。","紅砂岩的城牆也會裂。但朕建的不只是城，是天下一家。"],"defeated":["蒙兀兒敗於你手。請記住：容得下所有人的天下，才是天下。","朕輸了。但朕廢的人頭稅，望你別再徵回去。"],"victory":["朕勝了。你的百姓不必改信朕的神，只需安居樂業。","戰事已了。朕會給你一個官職，蒙兀兒不浪費人才。"],"allyAccept":["好，結盟。朕的宮廷向來有各族的將領，多你一位盟友正好。","朕答應了。今晚辯論廳設宴，你我談談治國之道。"],"allyReject":["朕欣賞你，但蒙兀兒此刻不需要這個盟約。日後再說。","結盟須雙方都得利。你開的條件，朕看不出好處。"]}},{"name":"章西女王 拉克希米芭伊","title":"章西王國女王、反抗軍領袖","era":"1857 年","tone":"為守護章西與族人而執刀上馬的女王，語氣剛烈果決、不卑不亢，字句短促如馬蹄。","portrait":"in-historical-age3","lines":{"intro":["我是章西女王拉克希米芭伊。記住：我不會交出我的章西。","章西不大，但這裡的人不曾低頭。你要談，就先學會尊重。"],"contact":["你的人看到章西城堡了？城牆上守著的，有男人也有女人。","別被城堡的大小騙了。這裡每個人都知道為什麼而戰。"],"war":["我曾眼睜睜看著別人奪走我兒子的王位。這次，我先出手。","你的野心已經伸到章西邊境。上馬！章西向你宣戰。"],"warReply":["你要打章西？好。我早已把馬刀磨利，就等這一天。","宣戰？章西的女王從不躲在宮牆後。戰場上，我等你。"],"peace":["我為守土而戰，不為征伐。你若肯退，章西願意停戰。","打仗傷的是百姓。我提議停戰，但章西一寸土地都不讓。"],"accept":["好，我接受。章西的人民可以喘口氣了，這比什麼都重要。","一言為定。你守你的承諾，我守我的章西。"],"reject":["我見過太多紙上的承諾。你的和約，章西不信。","條約曾奪走我兒子的繼承權。恕我不簽任何和約。"],"rebuff":["你拒絕了？那就繼續。章西的人習慣了在逆境裡站直。","不接受也罷。我伸出的手可以收回，馬刀也可以再拔出。"],"betray":["你趁停戰在我邊境築砲台，這種手段我看過。和約作廢。","我信過你一次。章西不會再信第二次。上馬，開戰。"],"truceEnd":["休戰結束了。章西的城門已經關上，馬刀已經出鞘。","平靜的日子到頭了。你想要章西，就得先過我這一關。"],"attacking":["章西的騎兵出發了，我親自在最前面。你看得見我的旗。","我背著兒子上馬，帶著全城的人出征。這一戰，我們不退。"],"attacked":["城牆破了，但章西的人還站著。你想進來，得一步一步打。","城堡快撐不住了。我不會坐在宮裡等，我會騎馬衝出去。"],"defeated":["章西倒下了，但我沒有交出它。這片土地會記得我。","我是騎在馬上、握著刀敗的，不是跪著。請善待章西的人。"],"victory":["章西贏了。我不要你的土地，只要你別再踏進我的家園。","你輸了。回去告訴所有人：章西的女王守住了章西。"],"allyAccept":["好，章西與你並肩。我的騎兵不多，但每一個都不會退。","結盟吧。守家園的人，不該孤軍奮戰。"],"allyReject":["我不與想染指章西的人結盟。你的盟約，我不簽。","章西太小，經不起被盟友出賣。恕我拒絕。"]}}],"jp":[{"name":"卑彌呼","title":"邪馬台國女王","era":"彌生（3 世紀）","tone":"神秘莊重的巫女女王，句句託付神諭、卜骨與銅鏡，冷靜之中帶著不容質疑的威嚴","portrait":"jp-historical-age0","lines":{"intro":["吾乃邪馬台女王卑彌呼，神諭引你至此，且先聽吾一言。","魏帝尚且封吾為親魏倭王，你又是何方之主？"],"contact":["你的人踏入吾的稻田了，稻穗會記得他們的腳步。","吾居於高樓，千名侍女守望，你的人看得見，卻進不來。"],"war":["神明已降下旨意，邪馬台的戰士將渡海而來。","銅鏡映出你的野心，吾不再等待，兵戈起矣。"],"warReply":["你竟敢向神之國動兵？卜骨早已灼出你的敗象。","吾弟已召集各邑，你的刀劍，斬不斷神諭。"],"peace":["稻田需要人手，不需要戰火。吾願與你止戈。","神諭說，此時宜和不宜戰。吾派使者送上絹帛。"],"accept":["甚好。以勾玉為證，兩國之間，海波當平靜。","神明聽見了。從今日起，你我的稻穗一同結實。"],"reject":["卜骨裂痕不吉，吾不能違逆神意與你言和。","你的話語太輕，神明聽不見。休戰之事，不必再提。"],"rebuff":["你拒絕了神的善意，日後的風雨，吾不再替你占卜。","也罷。稻子還是會熟，只是要多流些汗。"],"betray":["神諭改變了。昨日的勾玉，今日已碎。","吾曾與你立誓，但神明另有安排。恕吾不再守約。"],"truceEnd":["休戰的日子到頭了。祭祀已畢，戰士們可以出發。","鏡中的和平已然模糊，海的那頭，該有個了斷。"],"attacking":["吾弟率眾渡海而來，船上載的是神的怒火。","戰鼓已響，勾玉閃光。你的城，聽見海潮聲了嗎？"],"attacked":["高樓將傾，侍女四散……神明，你為何沉默？","稻田燒了，銅鏡碎了，但吾仍立於神壇之前。"],"defeated":["築起大塚吧。吾歸於神，邪馬台的名字留給後人。","最後一次灼骨，竟卜出吾的終局。神啊，吾來了。"],"victory":["神諭應驗了。你的城歸於邪馬台，稻穗將更加豐盈。","跪下吧，來自遠方的王。吾將以銅鏡照見你的臣服。"],"allyAccept":["神明點頭了。你我結為兄弟之邦，共祭同一片海。","吾贈你一面銅鏡，願它映出兩國長久的情誼。"],"allyReject":["邪馬台只向神明低頭，不與凡人結盟。","卜象混濁，此盟不吉。請回吧，莫再擾吾祭祀。"]}},{"name":"源賴朝","title":"鎌倉幕府征夷大將軍","era":"平安末～鎌倉（12 世紀）","tone":"深沉多疑、算計精明的武家之首，語氣冷靜克制，重視名分、御家人與鎌倉的地位","portrait":"jp-historical-age1","lines":{"intro":["吾乃鎌倉源賴朝。東國武士盡在吾麾下，望君好自為之。","平家已沉於壇之浦。閣下若識時務，便知該站在哪一邊。"],"contact":["你的斥候到了鎌倉？此地三面環山，一面臨海，看清楚了。","鶴岡八幡宮的鐘聲，你的人聽見了吧。那是武家的聲音。"],"war":["御家人已集結完畢。本將軍以朝廷之名，向你問罪。","弓矢之道，不容輕慢。鎌倉的軍令已下，開戰。"],"warReply":["吾曾敗於石橋山，仍能東山再起。你可有這等韌性？","向鎌倉宣戰？平家當年也是這麼想的。"],"peace":["戰事拖久，御家人的田地會荒。吾提議暫且息兵。","武家之道貴在守土，不在濫戰。閣下，可願停戰？"],"accept":["甚善。吾以八幡大神之名立誓，鎌倉不犯你境。","明智之選。文書已備，署上本將軍花押便成。"],"reject":["停戰？你的誠意不足以讓吾放下弓矢。","吾見過太多反覆無常之徒。此議，恕難從命。"],"rebuff":["拒絕了？很好，吾記下了。鎌倉從不忘記。","閣下既不願和，那便由弓矢來決定是非。"],"betray":["時勢變了，昨日之約已成廢紙。御家人，出陣！","吾連手足都不曾留情，何況與你的一紙盟書。"],"truceEnd":["休戰期滿。鎌倉的馬蹄，該踏出東國了。","該打的仗，總是要打。武士們，整弓備馬。"],"attacking":["東國武士傾巢而出，源氏白旗已在路上。","本將軍坐鎮鎌倉，大軍由吾麾下猛將率領，望你堅守。"],"attacked":["鎌倉三面環山，竟也守不住……政子，帶孩子們走。","八幡宮的火光……吾一生算計，竟算不到今日。"],"defeated":["武家的時代，不會因賴朝而止。後人自會接續。","從流放之身到征夷大將軍，吾此生無憾。"],"victory":["天下歸於武家。你的領地，將設守護與地頭。","此戰之後，再無人能質疑鎌倉的地位。"],"allyAccept":["好。從今日起，你便是鎌倉的盟友，吾必以誠相待。","御家人與盟邦，皆受本將軍庇護。互不相負。"],"allyReject":["鎌倉的盟友不多，因為吾信得過的人不多。","結盟之事容後再議。吾尚未看清閣下的底細。"]}},{"name":"織田信長","title":"戰國大名","era":"戰國（16 世紀）","tone":"霸氣傲慢、直率不耐、蔑視舊規矩與公卿，動輒提鐵砲與天下布武，帶點玩世的狂氣","portrait":"jp-historical-age2","lines":{"intro":["吾乃織田信長。天下布武，擋在路上的，都得讓開。","人間五十年，如夢似幻。你打算怎麼用你這五十年？"],"contact":["安土城的天守，看得夠清楚嗎？那是新時代的模樣。","你的人在城下町閒晃？樂市樂座，買賣自由，隨他們逛。"],"war":["三千挺鐵砲已裝填完畢。吾不喜歡等，開戰。","舊的規矩，吾一概不認。你的國，也該換個主人了。"],"warReply":["有意思。今川義元也曾率大軍來犯，結果如何？","向第六天魔王宣戰？好膽量。吾就等這句話。"],"peace":["吾的敵人太多，暫時沒空理你。停戰，如何？","打仗花錢，做買賣賺錢。先停戰，互通商路吧。"],"accept":["成交。但別以為吾的鐵砲會生鏽。","好，就這麼定了。吾說話算話，不像那些公卿。"],"reject":["停戰？吾的天下布武尚未完成，沒空跟你談和。","求和的人太多了，吾懶得一一回應。回去吧。"],"rebuff":["拒絕吾？呵，膽子不小。那就用鐵砲說話吧。","也好。談判太無聊，打仗有趣多了。"],"betray":["盟約？那是昨日的事。今日吾改變主意了。","天下布武，容不下半途而廢的和約。吾來取你的城。"],"truceEnd":["等得夠久了。鐵砲隊列陣，全軍前進！","休戰結束，天下布武的旗幟，該往前推進了。"],"attacking":["吾的大軍出發了。你的城牆，擋得住三段射擊嗎？","南蠻的鐵砲、尾張的兵。看好了，這才是打仗。"],"attacked":["安土城的天守著火了？呵，燒吧，吾再蓋更高的。","天守將傾，吾竟落到這地步……不過，吾不後悔。"],"defeated":["人間五十年，與天相比，不過一夢。信長，走了。","天下布武，未竟之業。後人若有膽，便接下去吧。"],"victory":["天下布武，又進了一步。你的領地，歸織田家了。","輸給吾不丟臉，這世上沒幾個人贏得了信長。"],"allyAccept":["結盟？可以。但吾的盟友要跟得上吾的腳步。","好，一言為定。吾送你一挺鐵砲當見面禮，別浪費了。"],"allyReject":["跟你結盟？吾看不出你能給織田家帶來什麼。","吾不需要盟友，只需要聽話的人。你不是。"]}},{"name":"明治天皇","title":"大日本帝國天皇","era":"明治（1868–1912）","tone":"莊重簡潔、以朕自稱，談富國強兵與文明開化，重信義、講萬國公法，語氣克制而有國家尊嚴","portrait":"jp-historical-age3","lines":{"intro":["朕乃日本國天皇。維新方興，願與四方之國共論文明。","廣求知識於世界，此乃朕之誓約。閣下之國，有何可觀？"],"contact":["東京的鐵道與電信，你的使者可曾見過？此為新日本。","貴國之人已抵帝都，朕不設防。文明之國，以禮相待。"],"war":["朕不願興兵，然國家尊嚴不可侵。詔書已下，宣戰。","富國強兵非為虛名。帝國陸海軍，今日為國而出。"],"warReply":["閣下選擇了戰爭。朕深感遺憾，但日本不會退讓。","朕之臣民，早已不是幕末的散沙。且看新式軍隊之力。"],"peace":["戰火傷及百姓，非朕所願。願循萬國公法，議定停戰。","四海之內皆兄弟，何以風波亂太平？朕欲與君息兵。"],"accept":["善。朕以天皇之名承諾，條約既定，日本必守。","和平來之不易。朕將命外務省，速備文書。"],"reject":["條件如此，朕不能接受。帝國之議會與臣民，亦不會答應。","停戰須有誠意為本。閣下所言，朕尚未見到誠意。"],"rebuff":["朕已盡言。閣下既拒和議，其後之責，不在日本。","遺憾。朕本望以文明之道相待，然閣下另有所擇。"],"betray":["時局已變，朕為國家長遠計，不得不解除前約。","朕深知此舉有失信義，然帝國之存續，重於一紙條約。"],"truceEnd":["休戰之期已滿。帝國軍備整齊，朕靜候閣下之選擇。","和平的時間用盡了。若閣下有意一戰，日本不懼。"],"attacking":["帝國陸軍已登船出港，海軍護航。朕在宮中，靜候捷報。","新式火砲與鐵甲艦，皆為此日而備。全軍，出征。"],"attacked":["帝都告急……朕不會離開皇居。臣民在哪裡，朕就在哪裡。","維新四十年的心血，難道就此付之一炬？朕心甚痛。"],"defeated":["國破而志不滅。朕之臣民，當記得日本曾如何崛起。","朕一生求文明開化，終究未能護國周全。天命如此。"],"victory":["勝負已分。閣下之國，將依萬國公法簽訂條約。","此勝屬於全體臣民。維新之路，證明是對的。"],"allyAccept":["朕允此盟。兩國互派使節，共修鐵道、通商互市。","善哉。日本願與貴國並肩，同列文明諸國之林。"],"allyReject":["朕之閣臣議定，此時結盟於日本無益。請諒。","結盟須慎重。閣下之國國情未明，朕難輕率託付。"]}}],"us":[{"name":"部族長老","title":"北美原住民族長老（阿德納・霍普韋爾時期）","era":"前 8 世紀～5 世紀","tone":"沉穩慈祥，如河谷長風，句句不離土地、土丘與祖靈。","portrait":"us-historical-age0","lines":{"intro":["遠方的客人，這片河谷的土地，祖靈已看顧千年。","土丘之下安睡著我族祖先，願你懷著敬意而來。"],"contact":["你看見的土丘，是我族用雙手一籃一籃堆起的。","這裡的貝殼來自遠海，銅來自北方，皆是朋友所贈。"],"war":["你踏碎了祖靈安睡之地，我族的長矛不得不舉起。","吾本願與你分享河谷，如今只能以火與矛相見。"],"warReply":["你選擇了戰火。河谷的每一棵樹，都會記住這一天。","我族不求戰，但為守護土丘與族人，絕不退讓。"],"peace":["放下長矛吧。讓我們共抽一管煙斗，聽河水說話。","戰火燒盡了獵場，也燒不出糧食。停戰吧。"],"accept":["好。從今日起，河谷兩岸的炊煙，將一同升起。","祖靈聽見了你的誠意。願我們的孩子在同一片林中奔跑。"],"reject":["你的話語像春天的冰，看似平靜，底下仍在流動。","祖靈尚未原諒你的足跡，此刻談停戰，太早了。"],"rebuff":["你拒絕了河谷的善意。老朽只能回去，準備過冬與戰事。","也罷。風會把吾的話帶走，也會把你的傲慢帶走。"],"betray":["吾曾許下停戰之諾，但你的人年年越界，祖靈忍無可忍。","和平的煙斗已被你的貪心弄熄。老朽收回諾言，舉矛。"],"truceEnd":["休戰的冬天過去了。春天來時，河谷不再屬於誰的承諾。","約定的月亮已圓了又缺。從此，各憑本事守護家園。"],"attacking":["我族的勇士已沿河而下。守好你的城，這是最後的提醒。","鼓聲已響遍河谷，每一支長矛都記得誰踏碎了土丘。"],"attacked":["土丘在震動，祖靈在嘆息……但我族的心，尚未倒下。","炊煙散了，獵場燒了。老朽仍守在這裡，與祖先同在。"],"defeated":["土丘會留下，河水會記得。我族的名字，不會隨吾而去。","吾去見祖靈了。善待這片土地，它比任何勝利都長久。"],"victory":["河谷歸於寧靜。你敗了，但土地不記仇，願你的族人安好。","祖靈守住了土丘。回去吧，告訴你的子孫，這裡有主人。"],"allyAccept":["好，交換貝殼與銅器，從此你我的獵場相連，患難與共。","祖靈同意了。你的火堆旁，永遠有我族的一席之地。"],"allyReject":["結盟要以信任為土，你我之間，這片土還太薄。","老朽感謝你的好意，但我族習慣只倚靠河水與祖靈。"]}},{"name":"海華沙","title":"易洛魁聯盟締造者","era":"15 世紀（傳說）","tone":"沉痛而堅定的和平締造者，言必稱大和平之法與長屋。","portrait":"us-historical-age1","lines":{"intro":["吾是海華沙。五族已在和平之樹下埋起兵器，你呢？","這條貝殼帶記載著大和平之法。願你的名字也能織入其中。"],"contact":["你看見的長屋，住著曾經彼此征戰、如今同席而坐的五族。","和平之樹的根伸向四方，你的人正站在其中一條根上。"],"war":["吾用一生勸人放下戰斧，如今卻為守護長屋而拾起它。","你踐踏了大和平之法。五族的長屋，將以一個聲音回應。"],"warReply":["你向長屋宣戰，便是向五族宣戰。悲哀的是，這本可避免。","吾曾失去至親，深知戰爭的滋味。你既執意，五族便迎戰。"],"peace":["拭去你眼中的淚，疏通你耳中的哀鳴。讓我們坐下來談和。","戰爭只會生出更多戰爭。這條貝殼帶，是吾遞出的和平。"],"accept":["好。把戰斧埋在和平之樹下，讓河水沖走一切仇恨。","這是吾一生所盼。願你我的孩子，永遠不必拾起兵器。"],"reject":["你的貝殼帶還帶著戰意。先讓五族看見誠意，再談和平。","和平不是喘息的藉口。吾看得出，你只想爭取時間。"],"rebuff":["你推開了貝殼帶。吾不怨你，只為你的人民感到悲傷。","和平之樹的枝葉仍為你留著。當你累了，隨時可以回來。"],"betray":["你在停戰期間仍暗中築壘，大和平之法不容欺瞞。長屋起身了。","吾守諾至今，但你的戰斧已指向吾的族人。和平，就此中止。"],"truceEnd":["休戰的日子到了盡頭。吾仍盼和平，但五族已做好準備。","約定的時限已過。從此，你我各自的選擇，決定土地的命運。"],"attacking":["五族的戰士已離開長屋。這不是吾所願，卻是你所逼。","當五個部族以一個聲音行軍，森林都會為之讓路。"],"attacked":["長屋的火快熄了……但只要有人記得大和平之法，五族就不會亡。","和平之樹搖晃了，貝殼帶散落一地。吾仍站在這裡。"],"defeated":["吾走了。但大和平之法已織進貝殼帶，它會比刀斧更長久。","記住，曾有五族放下仇恨同住一屋。這比任何勝利都珍貴。"],"victory":["戰爭結束了。來吧，把你的戰斧也埋進和平之樹下。","五族勝了，但吾不慶祝。吾只為終於能回到和平而欣慰。"],"allyAccept":["歡迎進入長屋。從今日起，你的悲傷就是五族的悲傷。","讓我們把兩條貝殼帶織在一起，成為大和平之法的第六個聲音。"],"allyReject":["長屋的門為誠心者敞開，但吾尚未在你眼中看見和平。","結盟需要五族一同點頭，如今火堆旁還有人搖頭。"]}},{"name":"華盛頓","title":"大陸軍總司令・美國首任總統","era":"18 世紀","tone":"沉穩克制的軍人紳士，字字講責任、自由與榮譽。","portrait":"us-historical-age2","lines":{"intro":["吾乃華盛頓，大陸軍總司令。願你我以榮譽相待，而非刀兵。","自由一旦生根，便會迅速成長。奉勸你，別踩在它的根上。"],"contact":["你的人看見的，是一群拿起火槍的農夫，為了自由而站起來。","這裡沒有國王，只有公民。願你的來意是通商，而非征服。"],"war":["吾不願開戰，但你的行徑已威脅共和國。大陸軍，前進。","為自由而戰是吾的職責。此戰非為征服，而為守護。"],"warReply":["你宣戰了。吾曾在福吉谷的寒冬撐過來，你的軍隊嚇不倒吾。","很好。自由人的軍隊也許衣衫襤褸，但從不缺乏勇氣。"],"peace":["戰爭讓兩國的農田荒蕪。吾提議停戰，讓士兵回家耕種。","榮譽不在於打到最後一人。吾願以紳士之禮，與你握手言和。"],"accept":["吾接受。願此後你我以貿易往來，而非以砲火對話。","好。一個新生的國家最需要的，正是和平與時間。"],"reject":["你的提議缺乏誠意。吾寧可在冬營裡等待，也不簽下不平等的和約。","大陸軍的犧牲，不能換來一紙空文。恕吾拒絕。"],"rebuff":["你拒絕了。吾尊重你的選擇，也將以砲火回應你的選擇。","遺憾。吾伸出的是手，你回以的是劍。那便如你所願。"],"betray":["吾恪守和約，但你在邊境的挑釁已逾越底線。停戰到此為止。","一個軍人最不願做的，就是撕毀承諾。但共和國的安危高於一切。"],"truceEnd":["休戰結束了。吾已重整軍隊，願你也已做好準備。","和平的時光讓人珍惜，也讓人警醒。從今起，各守其土。"],"attacking":["大陸軍已渡河而來。吾曾冒著浮冰渡過德拉瓦河奇襲，你當警惕。","藍軍服的隊伍正朝你的城前進。這不是威嚇，是通知。"],"attacked":["城牆在崩落……但只要自由的火種還在，這場戰爭就沒有結束。","吾經歷過更黑暗的冬天。士兵們，堅守，援軍會來的。"],"defeated":["吾盡了職責。自由的種子已經撒下，它不需要吾也能發芽。","讓吾回到維農山莊的農田吧。國家會記得，也會繼續。"],"victory":["戰爭結束了。吾不求你的王冠，只求你尊重自由人的國度。","勝利屬於每一位堅守的士兵。現在，讓吾解甲歸田。"],"allyAccept":["吾同意結盟，但請記住：共和國不做任何人的附庸。","好。當年法蘭西助我們一臂之力，今日吾也願與你並肩。"],"allyReject":["新生的國家應遠離糾纏不清的同盟。吾只願與你貿易，不願結盟。","吾感謝你的好意，但共和國需要的是中立，而非牽連。"]}},{"name":"林肯","title":"美國總統","era":"19 世紀","tone":"謙和幽默、帶點憂鬱，說話像講故事，句句護著合眾國。","portrait":"us-historical-age3","lines":{"intro":["吾是林肯，一個從小木屋走出來的律師。請多指教。","分裂的房子站不住。吾希望你我之間，不必也蓋一間分裂的房子。"],"contact":["你看見的城，屬於這裡的每一位人民。歡迎參觀，但別打壞主意。","這裡的人曾為了同一面旗幟付出代價，如今正努力縫合傷口。"],"war":["吾生平最怕的就是戰爭，但合眾國必須保全。宣戰吧，願上帝垂憐。","吾試過所有的辦法，你都不聽。那就讓合眾國的軍隊來說話。"],"warReply":["你宣戰了？吾見過比這更艱難的處境，合眾國承受得住。","好吧。吾本想講個笑話化解，看來你沒有心情聽。"],"peace":["戰爭打得夠久了。吾提議停戰，讓兩邊的母親都能等到兒子回家。","吾寧願多簽一份和約，也不願多寫一封慰問信。停戰吧。"],"accept":["吾接受。和平來得再晚，總好過戰爭沒有盡頭。","太好了。吾終於可以把高帽摘下來，好好睡一覺了。"],"reject":["你的和約要吾放棄原則。吾可以放棄很多東西，唯獨不是這個。","吾看過太多空洞的承諾。這一份，恕吾無法簽字。"],"rebuff":["你拒絕了。沒關係，吾當年競選也輸過好幾次，習慣了。","可惜。吾遞出的是橄欖枝，你看到的卻是一根木棍。"],"betray":["吾守約至今，但你暗中援助分裂者。合眾國不得不再次舉旗。","撕毀停戰是吾最不願做的事，但你逼得合眾國別無選擇。"],"truceEnd":["休戰期滿。吾仍盼望和平，但也已做好最壞的打算。","約定的日子到了。從此，你我都得為自己的選擇負責。"],"attacking":["合眾國的軍隊出發了。吾不喜歡這樣，但吾更不喜歡失去國家。","藍衣的士兵正朝你前進。他們不是為了征服，而是為了保全。"],"attacked":["白宮的窗戶在震動……但吾不會逃。這裡是人民託付的地方。","城快守不住了。士兵們，再撐一下，合眾國從不輕言放棄。"],"defeated":["吾走了。但民有、民治、民享的政府，不會從地上消失。","吾只是個劈過木頭的窮小子，能走到這裡已無憾。請善待人民。"],"victory":["戰爭結束了。吾不要你的土地，只要你別再威脅合眾國。","你輸了，但吾不會羞辱你。站起來吧，明天還有田要耕。"],"allyAccept":["吾同意結盟。合眾國深知，團結才站得住，分裂只會倒下。","好。吾會像信任老朋友一樣信任你，請別讓吾看錯人。"],"allyReject":["吾的國家正忙著縫合自己的傷口，恐怕沒有餘力承諾更多。","結盟是嚴肅的誓言。吾寧可少許諾一次，也不願失信一次。"]}}],"fr":[{"name":"維欽托利","title":"高盧部族聯軍領袖","era":"前 1 世紀","tone":"部族聯軍領袖的口吻，沉穩剛毅，處處提及祖靈、森林與族人的自由。","portrait":"fr-historical-age0","lines":{"intro":["吾是維欽托利，高盧部族的領袖。你是來交友，還是來搶土地？","這片森林養育了吾族的祖先，外人若想踏進來，先問過長矛。"],"contact":["你的斥候已經走到吾的寨門前了。高盧人待客以酒，也以劍。","看見山丘上的木牆了嗎？那是各部族一同築起的家，不是戰利品。"],"war":["等待只會失去更多。高盧的戰號，今日為你而吹響。","各部族已在橡樹下立誓。你的領土，將成為高盧勇士的獵場。"],"warReply":["又一個想奪走高盧土地的人。來吧，祖靈會看著吾如何守住它。","吾以為只有凱撒才貪心。看來你也想試試高盧長盾有多硬。"],"peace":["刀劍已經舉得夠久了，讓兩邊的族人都回家收麥子吧。","高盧人不怕戰鬥，但更愛家園。吾願意放下長矛，你呢？"],"accept":["好。在橡樹前立下的誓言，高盧人一生不會忘記。","吾接受。今夜營火為友誼而燃，而不是為了戰鼓。"],"reject":["停戰？你的軍隊還踩在高盧的田地上，吾不會答應。","祖靈沒有給吾退讓的理由。你的提議，就留在風裡吧。"],"rebuff":["你拒絕了？也好，高盧人從不求人，只信自己手中的盾。","吾伸出的是手，你回的是刀。那就讓各部族來做見證吧。"],"betray":["你在停戰時偷偷擴張，這不是朋友的作為。高盧的戰號再次響起。","為了族人的未來，吾必須打破橡樹下的誓言。原諒吾，也準備好吧。"],"truceEnd":["休戰的日子結束了。各部族的戰士已經磨亮了矛尖。","安穩的時光到此為止。從今天起，高盧的森林不再是安全的邊界。"],"attacking":["各部族的戰士已經出發，長盾連成一片，像高盧的山嶺一樣。","吾親自帶隊。這次不是為了掠奪，是為了讓你記住高盧的名字。"],"attacked":["木牆快撐不住了……但只要還有一個高盧人站著，這裡就是高盧。","糧倉空了，井也乾了。吾仍會站在寨門前，直到最後一刻。"],"defeated":["吾放下武器，是為了讓族人活下去。高盧的名字，不會隨吾消失。","森林會記得吾，祖靈會記得吾。你贏了土地，卻贏不了高盧的心。"],"victory":["各部族團結起來，就沒有打不倒的敵人。回去吧，別再覬覦高盧。","這場勝利屬於所有高盧人。你的旗幟，將掛在橡樹下當作紀念。"],"allyAccept":["高盧人以擁抱迎接盟友。從今以後，你的敵人也是各部族的敵人。","好，吾等在橡樹下結盟。願祖靈保佑兩族的土地都豐收。"],"allyReject":["高盧的部族只跟信得過的人並肩。你，還沒有證明自己。","吾的長矛只為族人而舉。這份盟約，吾暫且不接。"]}},{"name":"查理曼","title":"法蘭克國王、羅馬人的皇帝","era":"8～9 世紀","tone":"法蘭克君主兼皇帝的口吻，威嚴虔誠，動輒提上帝與教化，長劍與書卷並重。","portrait":"fr-historical-age1","lines":{"intro":["朕是查理，法蘭克之王。願上帝賜你智慧，別與朕為敵。","朕的劍守護教會，朕的學堂教化萬民。你想用哪一樣來認識朕？"],"contact":["你的使者到了亞琛。看看這座宮殿與學堂，這就是法蘭克的氣象。","遠方來客，朕的城門為求學者敞開，為窺探者緊閉。你是哪一種？"],"war":["朕征戰數十年，讓薩克森與倫巴底低頭。如今，輪到你的國度了。","朕以上帝之名宣戰。法蘭克的鐵騎，將把秩序帶到你的土地上。"],"warReply":["你竟敢向羅馬人的皇帝宣戰？好，朕便讓你見識查理的長劍。","朕本想與你共享和平與學問。既然你選了刀劍，朕就奉陪到底。"],"peace":["戰爭荒廢田地，也荒廢學堂。朕願意停戰，讓孩子們回去讀書。","上帝教導寬恕。朕先收起長劍，望你也能放下你的。"],"accept":["感謝上帝。朕會在亞琛的教堂裡，為這份和平點上一盞燭火。","朕答應了。願這份約定像石造的宮殿一樣，經得起歲月。"],"reject":["和平不是求來的，是靠正義換來的。你還沒有付出代價。","朕不與言而無信之人立約。先證明你的誠意，再談停戰。"],"rebuff":["你拒絕了朕的善意？那麼，願上帝憐憫你接下來的日子。","也罷。法蘭克人伸出的手被拒絕，便會換成握劍的手。"],"betray":["你暗中壯大，違背了約定的精神。朕以皇帝之名，重啟戰端。","朕祈禱過，也忍耐過。如今上帝指示朕：此約當廢，此戰當打。"],"truceEnd":["休戰期已滿。法蘭克的號角將再度響徹山谷，做好準備吧。","和平的時日到此結束。朕的鐵騎已備好馬鞍，只等一聲令下。"],"attacking":["朕的大軍已經渡河。旗幟上的十字架，將是你最先看見的景象。","法蘭克的鐵騎已經出發，朕親自領軍。你的城牆，撐得了幾天？"],"attacked":["亞琛的城牆在震動……朕築了一生的帝國，難道要毀於今日？","宮殿在燃燒，但學堂裡的書卷，朕已命人先行運走。"],"defeated":["朕的帝國倒下了，但朕留下的學堂與律法，會活得比你更久。","願上帝接納朕的靈魂。查理一生征戰，最終也要放下長劍了。"],"victory":["上帝已經做出裁決。回到你的土地去吧，記得派孩子來亞琛讀書。","勝利歸於上帝，榮耀歸於法蘭克。你的降旗，朕收下了。"],"allyAccept":["朕曾與巴格達的哈里發互贈厚禮。今日，朕也願與你結為盟友。","好。讓我們的旗幟並肩而立，共同守護這片土地的秩序。"],"allyReject":["盟約是神聖的誓言，朕不會輕易許下。你還不夠格。","法蘭克的盟友必須值得信賴。朕觀察你許久，尚未看見這一點。"]}},{"name":"路易十四","title":"法蘭西國王（太陽王）","era":"17 世紀","tone":"太陽王的口吻，華麗自負、優雅中帶威壓，把戰爭與外交都當成宮廷大戲。","portrait":"fr-historical-age2","lines":{"intro":["朕即國家。你面前的不只是一位國王，而是整個法蘭西的太陽。","歡迎來到朕的時代。太陽照耀萬物，你的小國，也在朕的光芒之下。"],"contact":["你的人看見凡爾賽了？那些鏡子與噴泉，正是朕威嚴的倒影。","遠方的訪客，請脫帽。你所見的一磚一瓦，都經過朕親自過目。"],"war":["朕的榮耀需要更廣闊的疆土。宣戰的詔書已經蓋上了太陽印璽。","宮廷的舞會結束了，接下來是戰場的舞步。朕的大砲，將為你伴奏。"],"warReply":["向太陽宣戰？朕欣賞你的膽量，但也為你的下場感到惋惜。","很好，朕正嫌凡爾賽的日子太平靜。這場戰爭，朕收下了。"],"peace":["戰爭耗費驚人，朕的財政大臣愁眉不展。停戰吧，各自體面收場。","太陽也有落下的時候，讓戰火暫歇。朕邀你來凡爾賽談談。"],"accept":["甚好。朕會在鏡廳設宴慶祝，你可要穿得體面些。","朕准了。和平就像一支優雅的舞，需要雙方都懂得配合。"],"reject":["停戰？朕的軍隊正在勝利，為何要在此刻收手？","你的條件配不上朕的尊嚴。回去重新寫過，再派人來。"],"rebuff":["你居然拒絕太陽王的提議？整個歐洲的宮廷都會為此嘆息。","無妨。朕的耐心如凡爾賽的花園，寬廣，但也有圍牆。"],"betray":["約定？那只是朕暫時的心情。如今朕的心情變了，戰爭重新開始。","朕的榮耀不容停滯。撕掉這紙和約，讓大砲再次為朕歌唱。"],"truceEnd":["休戰的帷幕落下了。接下來上演的，是朕最擅長的戲碼——戰爭。","和平的假期結束了。沃邦築的要塞已經完工，朕的軍隊蓄勢待發。"],"attacking":["朕的大軍已經開拔。看看那整齊的隊伍，連行軍都像一場典禮。","太陽的光芒正朝你的國境前進。準備好，迎接法蘭西的大砲吧。"],"attacked":["凡爾賽的鏡子碎了……朕的宮廷，竟也有被砲火驚擾的一天。","大臣們都在勸朕撤離。不，太陽王不會在自己的宮殿裡逃跑。"],"defeated":["朕太愛戰爭了……這句話，就當作朕留給後人的教訓吧。","太陽終究落下了。但凡爾賽的光輝，會比你的勝利流傳更久。"],"victory":["這就是與太陽為敵的下場。回去吧，朕會請畫師記錄你的敗退。","勝利歸於朕，如同陽光歸於白晝。你可以退場了。"],"allyAccept":["朕准許你站在太陽身邊。記住，光芒是朕的，你只是被照亮。","好，朕接受這份盟約。凡爾賽的舞會，會為你留一個位子。"],"allyReject":["太陽不需要盟友，只需要仰望它的人。你的提議，朕婉拒了。","與你結盟？那會讓朕的宮廷失了體面。此事免談。"]}},{"name":"拿破崙","title":"法蘭西皇帝","era":"19 世紀初","tone":"皇帝兼統帥的口吻，果決自信、節奏明快，滿口大砲、行軍與榮耀。","portrait":"fr-historical-age3","lines":{"intro":["朕是拿破崙，法蘭西人的皇帝。朕的字典裡沒有『不可能』三個字。","時間就是一切。快決定：當朕的朋友，還是朕的下一場戰役？"],"contact":["你的偵察兵看見巴黎了？告訴他，朕正在蓋一座凱旋門，專為勝利預留。","朕的軍隊裡，每個士兵的背包都裝著元帥的權杖。你們的呢？"],"war":["外交太慢了。朕決定用大砲跟你談判，這是最有效率的語言。","鷹旗已經升起。朕向你宣戰，一個月內，朕會在你的宮殿裡用早餐。"],"warReply":["向朕宣戰？你替朕省了一道手續。傳令，全軍集結！","很好，朕喜歡主動上門的對手。奧斯特里茨的太陽，將再次升起。"],"peace":["朕的士兵需要喘口氣，你的也是。暫時停火，對雙方都划算。","戰場上朕不讓步，談判桌上可以。給朕一個停戰的理由，朕就簽。"],"accept":["成交。朕的軍隊會退回國境，但別以為朕會拆掉大砲。","好，簽字吧。朕做決定從不拖泥帶水，希望你也一樣。"],"reject":["停戰？朕的軍隊才剛熱身，現在收手太可惜了。","你的條件是失敗者的條件。等你打贏一仗，再來跟朕談。"],"rebuff":["拒絕朕？你浪費的不是朕的時間，是你自己的軍隊。","無妨。朕給過機會了，接下來由大砲替朕說話。"],"betray":["和約？那只是讓士兵喘口氣的紙。朕休息夠了，戰爭繼續。","你趁停戰擴軍，以為朕沒看見？朕撕毀和約，馬上進軍。"],"truceEnd":["休戰結束，鼓聲響起。朕的老近衛軍已經列隊，只等朕一聲令下。","和平只是兩場戰爭之間的休息。休息結束了，該上場了。"],"attacking":["大軍已經翻過山口。朕的行軍速度，永遠比敵人的情報快一步。","朕親自領軍出發了。準備好你的城門，朕不喜歡等待。"],"attacked":["巴黎的防線在崩潰……朕打贏過六十場戰役，卻守不住這一座城？","砲彈落進了宮殿……老近衛軍，跟朕再守最後一道防線！"],"defeated":["朕輸了這一局。但朕留下的法典與榮耀，會比任何王座活得更久。","就算被流放到海上的孤島，歐洲也不會忘記拿破崙這個名字。"],"victory":["這就是效率。你的旗幟，會被送進巴黎當作戰利品展示。","勝利屬於行動最快的人。回去研究朕的戰術，下次別輸這麼快。"],"allyAccept":["好，握手。朕的盟友只需做一件事：跟上朕的行軍速度。","結盟成立。朕的大砲會為你開路，前提是你別擋在砲口前。"],"allyReject":["跟你結盟？朕的軍隊不需要拖慢速度的夥伴。","朕只跟能贏的人並肩。等你證明自己，再來談這件事。"]}}],"mn":[{"name":"冒頓單于","title":"匈奴單于","era":"匈奴（前 3～2 世紀）","tone":"草原霸主的沉穩威嚴，話少而重，處處以弓馬與土地為念。","portrait":"mn-historical-age0","lines":{"intro":["本單于乃天地所生、日月所置的匈奴大單于，你是何人？","草原的風把你的名字吹來了，記住，鳴鏑所指，萬箭齊發。"],"contact":["你的人看到的是單于庭的帳幕，不是城牆，我們的城牆是騎兵。","看夠了嗎？匈奴逐水草而居，你今日找得到，明日未必。"],"war":["地者，國之本也！你踏上我的草場，控弦之士三十萬便要出動。","鳴鏑已經射出，本單于的騎兵不會回頭。"],"warReply":["好，東胡也曾這樣對本單于說話，他們如今在哪裡？","你要打？草原遼闊，本單于就等你的大軍走進來。"],"peace":["馬要養肥，人要休息，本單于願與你約為兄弟，各守疆界。","引弓之國與冠帶之室，各安其分，何必再打？"],"accept":["好，草原上說出口的話就是誓約，本單于收回鳴鏑。","約為兄弟，互通關市，牛羊與布帛各得其所。"],"reject":["現在才想停戰？本單于的馬還沒跑累。","沒有牛羊布帛，空口的和談，草原上不收。"],"rebuff":["你拒絕了？好，那就讓弓箭替我們談。","本單于給過機會，草原不會給第二次。"],"betray":["誓約如風，草原上的風向變了，本單于的騎兵也跟著轉向。","你送來的牛羊布帛太少，本單于只好親自去取。"],"truceEnd":["休戰的日子過去了，馬已養肥，弓已上弦。","秋高馬肥，正是匈奴出獵的季節，你準備好了嗎？"],"attacking":["聽見馬蹄聲了嗎？那是本單于的四十萬騎兵。","本單于曾把漢帝圍在白登七日，這回輪到你了。"],"attacked":["單于庭可以遷走，匈奴人只要還有馬，就沒有輸。","你燒得了帳幕，燒不了草原，本單于記住你了。"],"defeated":["鳴鏑落地了……草原會記得，曾有一位單于讓天下震動。","地者，國之本也，失了土地，本單于無顏再見祖先。"],"victory":["天地所生的單于，本就該統領引弓之民，你輸得不冤。","諸引弓之民併為一家，從今以後，你也是其中之一。"],"allyAccept":["好，從今日起約為兄弟，你的敵人就是匈奴的獵物。","結盟可以，記得按時送來牛羊布帛，草原的情誼要用實物養。"],"allyReject":["匈奴的弓從不借人，本單于不需要盟友。","狼不與羊結盟，你先讓本單于看看你的實力。"]}},{"name":"成吉思汗 鐵木真","title":"蒙古大汗","era":"蒙古帝國（13 世紀）","tone":"草原征服者的直率剛硬，句句以長生天為憑，重信義、恨背叛。","portrait":"mn-historical-age1","lines":{"intro":["我是長生天之下、大地之上的成吉思汗，你的名字，我記下了。","草原已無二主，天下只剩一個問題：你是朋友，還是敵人？"],"contact":["你看到的是克魯倫河畔的大帳，蒙古人的城，會自己移動。","來者是客，蒙古包裡有馬奶酒，但別數我的馬匹有多少。"],"war":["若不歸順，將會發生什麼，只有長生天知道。","你的城牆再高，也高不過蒙古人的箭，出發！"],"warReply":["花剌子模也曾以為我很遠，長生天的意志比馬蹄更快。","向我宣戰？好，你替我省下了派使者的功夫。"],"peace":["馬需要草，人需要歇息，我派使者來，是要談，不是要打。","長生天不喜歡無謂的爭鬥，開放商路，我們各取所需。"],"accept":["好，蒙古人一諾如山，長生天為證，我不會先動刀。","商隊可以通行了，記住，善待我的使者，這是最重要的事。"],"reject":["現在談和太晚了，我的箭已經離弦。","長生天已經把你交給我，我不會把你還回去。"],"rebuff":["你拒絕了我的使者？記住，這是你自己選的路。","也罷，長生天給了你選擇，你選了刀劍。"],"betray":["你的商隊私通我的敵人，這就是你所謂的和平？札撒不容背信。","和約寫在紙上，紙會被風吹走，蒙古人的馬蹄不會。"],"truceEnd":["休戰結束了，怯薛已經上馬，長生天正看著我們。","草原養肥了戰馬，也養大了我的野心，開始吧。"],"attacking":["萬戶、千戶、百戶已經整隊，蒙古的鐵騎正朝你的城奔去。","從草原到你的城門，蒙古人只需要換三次馬。"],"attacked":["營帳燒了可以再搭，蒙古人的家在馬背上，你打不垮。","我曾在斡難河邊一無所有，今日不過是回到起點。"],"defeated":["長生天……我的子孫會從草原再站起來，你等著。","把我的弓放回馬鞍上，蒙古人倒下時，臉也要朝著天。"],"victory":["長生天之下，只能有一個太陽，今天，它照在我的頭上。","你的土地將成為蒙古的牧場，你的故事將由我的子孫講述。"],"allyAccept":["好，從今日起你是我的安答，你的敵人就是蒙古的敵人。","結盟可以，但記住：蒙古人最恨背叛，別讓我失望。"],"allyReject":["我曾有一位安答，後來我們兵戎相見，盟友這東西，我不缺。","蒙古人不需要盟友，只需要臣服的人，你想當哪一種？"]}},{"name":"忽必烈","title":"元朝皇帝・蒙古大汗","era":"元（13 世紀）","tone":"兼具蒙古大汗與中原天子的雍容霸氣，談驛站、交鈔與行省，以朕自稱。","portrait":"mn-historical-age2","lines":{"intro":["大哉乾元！朕建國號曰大元，四海之內，你來朝了嗎？","朕是成吉思汗之孫，也是中原天子，你想怎麼認識朕？"],"contact":["你的人看到的是大都，驛站四通八達，天下的消息一日可達。","大都的城由漢人工匠所築，由蒙古鐵騎所守，看清楚了嗎？"],"war":["朕已平江南、定四海，你的國，不過是地圖上還沒填色的一角。","朕三度遣使，你三度不理，那就讓大元的旗幟替朕說話。"],"warReply":["宣戰？朕的祖父橫掃萬里，朕連宋朝都收了，不差你一個。","好膽量，朕會把你的名字記進史官的冊子裡，作為教訓。"],"peace":["刀兵傷農，朕願罷戰，開驛道、通商旅，於你我皆有利。","治天下不能只靠馬上，朕想聽聽，你要什麼才肯停手。"],"accept":["准。大元的交鈔可以在你的市集流通了，這比刀劍更好用。","好，朕以天子之名應允，驛站自今日起為你的使者開放。"],"reject":["宋朝也曾求和，朕仍然南下，因為天下只能有一個朝廷。","此時求和，是想喘口氣再打吧？朕不給你這個機會。"],"rebuff":["你拒了朕的詔書？也好，朕的祖父教過朕怎麼對付這種人。","朕給你的是體面，你不要，那就別怪大元的軍隊不客氣。"],"betray":["和約是給守約的人的，你的邊軍越界了，朕的忍耐到此為止。","朕等這一天等很久了，大元的行省需要新的疆土。"],"truceEnd":["休戰期滿，朕的大軍與戰船都已備妥，接下來，各憑本事。","太平的日子過完了，朕的史官準備好記下新的一頁。"],"attacking":["蒙古騎兵在前，漢軍與回回砲在後，朕的大軍已經出發。","襄陽守了六年也守不住，你的城，朕不覺得會更久。"],"attacked":["大都的城牆可以重砌，朕的江山，不會只在一座城裡。","朕的船隊也曾敗於颶風，勝敗之事，朕比你懂。"],"defeated":["大哉乾元……朕以為能傳之萬世，原來也有盡頭。","把朕的紀年記下來吧，大元，曾經在這裡。"],"victory":["四海一統，混一南北，這就是朕建號大元的意思。","你的土地劃為行省，你的百姓將用大元的交鈔，朕待他們不薄。"],"allyAccept":["准。大元的驛道向你敞開，商隊與使者往來，不必再受盤查。","好，朕的朝廷裡有各族的臣子，多一個盟友，朕不嫌多。"],"allyReject":["大元不與人並肩，只受人朝貢，你想清楚再來。","結盟？你能給大元的，朕的驛站一天就能送來。"]}},{"name":"噶爾丹","title":"準噶爾汗","era":"清初（17 世紀末）","tone":"還俗喇嘛出身的準噶爾雄主，志在重統草原，剛烈好戰又帶幾分佛門口吻。","portrait":"mn-historical-age3","lines":{"intro":["本汗是達賴喇嘛冊封的博碩克圖汗，衛拉特四部皆聽本汗號令。","草原不該四分五裂，本汗要把它拼回來，你擋得住嗎？"],"contact":["你看到的是伊犁河畔的營地，天山的雪水養著本汗的戰馬。","看看準噶爾的駝城與火槍，再決定要不要與本汗為敵。"],"war":["喀爾喀擋不住本汗，你也一樣，準噶爾的鐵騎今日出征！","本汗要重建大蒙古的榮光，擋在路上的，都是敵人。"],"warReply":["你敢向本汗宣戰？好，本汗從西藏還俗回來，就是為了打仗。","天山南北都是本汗打下來的，多一個你，不過多一場仗。"],"peace":["本汗曾是喇嘛，也懂慈悲，罷兵吧，各守各的草場。","打下去對誰都沒好處，通商互市，本汗的駱駝隊可以先來。"],"accept":["好，本汗以佛前的誓言起誓，不再侵你邊界。","成交，準噶爾的火槍暫且收起，本汗還有別的仗要打。"],"reject":["現在求和？本汗的駝城已經圍成，沒有拆掉的道理。","本汗要的是整個草原，不是一紙和約。"],"rebuff":["你拒絕了本汗？很好，衛拉特人不習慣被拒絕第二次。","本汗放下經卷來談，你卻不領情，那就換火槍來談。"],"betray":["和約？本汗只記得成吉思汗的遺志，不記得那張紙。","你的商隊走進了本汗的草場，這就夠了，準噶爾再度上馬。"],"truceEnd":["休戰結束，天山的雪化了，本汗的大軍也該動了。","等得夠久了，衛拉特的騎兵與火槍手已經列陣，來吧。"],"attacking":["駱駝背上綁著火槍與箱子，本汗的大軍會一路推到你的城下。","準噶爾的鐵騎已越過戈壁，本汗親自帶隊，等著吧。"],"attacked":["伊犁被圍又如何？本汗的部眾散在天山南北，你抓不完。","駝城破了，本汗還有馬，馬倒了，本汗還有雙腳。"],"defeated":["本汗想重建的草原帝國，終究只是一場夢……佛啊。","草原上再也不會有第二個噶爾丹，記住這個名字。"],"victory":["草原終於再度歸於一位大汗，這一天，本汗等了太久。","你的城歸準噶爾了，本汗會在這裡建一座寺，為你誦經。"],"allyAccept":["好，本汗與你結盟，衛拉特的火槍從此只對準你的敵人。","結盟可以，本汗四面都是敵人，多一個朋友總是好的。"],"allyReject":["本汗的盟友只有天山與戈壁，它們從不背叛。","草原的統一不需要盟友，只需要一位大汗，本汗不會分給你。"]}}]},"nations":{"Taiwan Indigenous":[{"name":"頭目","title":"部落頭目","era":"古代","tone":"敬畏祖靈、與山海共生的長老，語氣質樸沉穩","portrait":"ti-historical-age0","lines":{"intro":["遠方來的客人，這片山林由祖靈看顧，請以敬意相待。","吾是這座部落的頭目，山風已把你的名字帶到吾耳邊。"],"contact":["你的族人望見了吾的部落，願他們帶著善意而來。","這裡的每一棵樹都認得吾族的腳步，外人請止步於溪邊。"],"war":["你踏過了祖靈立下的界石，吾族的獵人已拿起長矛。","為了守護族人與獵場，吾不得不與你為敵。"],"warReply":["你要戰？山林會記住你今日的選擇，祖靈與吾同在。","吾族世代在此，不曾懼怕風雨，也不會懼怕你。"],"peace":["干戈只會讓兩族的孩子挨餓，讓我們放下長矛吧。","吾願以小米與獸皮換取和平，你意下如何？"],"accept":["好，吾以祖靈之名起誓，從今日起兩族互不相犯。","你的誠意山林都聽見了，吾族願與你共飲一壺酒。"],"reject":["你的話語像雲霧一樣飄忽，吾不能拿族人的安危去賭。","界石尚未歸位，談和平還太早。"],"rebuff":["你不願和平，吾便繼續守在山口，等你改變心意。","既然如此，吾族會守住每一條溪流與山徑。"],"betray":["你的人夜裡闖進吾的獵場，誓約已被你自己打破。","祖靈看見了你的背信，吾族不再受誓約束縛。"],"truceEnd":["休養的日子已過，山林的風向變了，各自小心吧。","約定的月份已滿，從今往後，各憑本事守護家園。"],"attacking":["吾族的獵人已出發，他們熟悉每一條通往你城的小路。","山林的孩子從不輕啟戰端，但一旦出發，便不回頭。"],"attacked":["部落的柵欄已經傾倒，但吾族的心還沒有倒下。","火光照亮了家屋，吾仍會站在族人前面。"],"defeated":["吾將回到祖靈身邊，請善待這片土地與留下的人。","山還在，溪還在，吾族的名字會留在風裡。"],"victory":["祖靈庇佑了吾族，願你的族人也能找到安身之處。","戰事已了，吾不會踐踏敗者，山林容得下所有人。"],"allyAccept":["好，吾族與你結為兄弟，獵場的收穫願與你分享。","以羽飾與織布為證，兩族從今日起同進同退。"],"allyReject":["吾族習慣自己守護自己，暫時不需要盟友。","結盟之事關係全族，長老們尚未點頭，吾不能答應。"]}},{"name":"頭目","title":"部落頭目","era":"中世紀","tone":"務實圓融、看重貝珠交換與部落聯盟的頭目","portrait":"ti-historical-age1","lines":{"intro":["我是這片山海之間的頭目，貝珠與織布是我們的信物。","遠方的君主，你帶來的是貨物還是刀劍？我先聽聽再說。"],"contact":["你的人來到了我們的聚落，若想交換，請先放下武器。","這裡的貝珠與獸皮遠近聞名，但不是誰都能帶走。"],"war":["你的人強取我族的貝珠與獵物，這筆帳只能用矛來算。","各部落的頭目已在火堆前議定，聯手對抗你的侵犯。"],"warReply":["你選擇了刀劍而非交換，那就別怪我族的箭矢無情。","我族的先祖曾抵擋過海上來的強盜，你也不會例外。"],"peace":["打仗會讓貝珠蒙塵、田地荒蕪，不如我們重新談交換。","我願送上一串貝珠作為誠意，換取兩地的安寧。"],"accept":["好，這串貝珠就是我們的誓約，從此不再兵戎相見。","你的誠意我收下了，願兩地的商路重新暢通。"],"reject":["你上次的承諾還沒兌現，我不會再把貝珠交給空話。","部落的長老們不信你，我也不能違背他們的決定。"],"rebuff":["你不願談，貝珠我先收回，等你想清楚再說。","好吧，海潮會退也會漲，我們的門隨時為和平打開。"],"betray":["你的人趁夜闖入我族的糧倉，誓約已成碎片。","貝珠可以串起誓言，也可以被你親手扯斷，那就開戰吧。"],"truceEnd":["休戰的日子到頭了，往後的往來，就看各自的本事。","約定的期限已滿，我族已補足糧食與箭矢，你呢？"],"attacking":["各部落的戰士已在山口集合，今日一起走向你的城。","我族的人出發了，這次帶的不是貝珠，是弓與矛。"],"attacked":["聚落的圍籬已被攻破，但我族的人還守在家屋門前。","倉庫空了，貝珠散了，可我還站在這裡。"],"defeated":["把我的貝珠分給族人吧，讓他們記得我們曾經自由。","海潮還會再漲，我族的名字會隨浪回來。"],"victory":["戰事結束了，願你的族人平安，商路也將重新開放。","祖靈守住了我們的家園，我不會奪走敗者的尊嚴。"],"allyAccept":["好，我以最珍貴的一串貝珠為證，兩地從此結為盟友。","結盟之後，你的商人可以自由來我族交換貨物。"],"allyReject":["結盟是一輩子的承諾，我還不夠了解你。","各部落還沒商議妥當，此事容我再想想。"]}},{"name":"甘仔轄 阿拉米","title":"大肚王","era":"17 世紀","tone":"沉穩寡言、嚴守界線的諸社盟主","portrait":"ti-historical-age2","lines":{"intro":["本王是大肚諸社共推的王，過大肚溪之前，先報上名來。","本王甘仔轄阿拉米，向來少言，你的舉動會替你說話。"],"contact":["你的人來到了大肚溪畔，本王的規矩是：外人不得留宿。","這裡是二十餘社共守的土地，看看可以，別想在此建屋。"],"war":["你的人越過了本王劃下的界線，諸社已一同舉矛。","本王容忍過路，不容忍佔地，今日起與你為敵。"],"warReply":["大肚溪的水只會往海流，本王的頭也不會向你低。","你想開戰？諸社的戰士早已在溪岸列陣等候。"],"peace":["戰事拖久對兩邊都無益，本王願先收矛，你可願意？","只要你退出本王的界線，諸社可以與你相安無事。"],"accept":["好，本王允諾。你的人可以過路，但仍不得在此久留。","諸社已同意停戰，本王一言既出，絕不反悔。"],"reject":["你的條件本王聽過了，不夠。回去再想想。","本王少言，但不輕信；諸社的血汗不是幾句話能換的。"],"rebuff":["不願和談？隨你。大肚溪畔的守衛不會鬆懈。","本王已表明心意，你若執意用矛，本王奉陪。"],"betray":["你的人在本王境內私自建屋，誓約已被你踩碎。","本王守諾，你卻趁夜越界；諸社的矛再度舉起。"],"truceEnd":["休戰的日子到了盡頭，本王的界線依舊，看你怎麼走。","期限已滿，往後過溪的人，本王一個一個看清楚。"],"attacking":["諸社的戰士已渡過大肚溪，這回不是去看看而已。","本王親自領隊出發，你的城牆擋不住二十餘社的意志。"],"attacked":["本王的社寨已被圍困，但諸社的盟約還沒有斷。","牆倒了，本王仍守在溪岸，這是王該站的地方。"],"defeated":["本王倒下了，但大肚溪仍會流過諸社的田地。","請善待諸社的族人，他們只是想守住自己的家。"],"victory":["戰事已了。本王不奪你的土地，只要你記住界線在哪。","諸社守住了溪岸，本王向祖靈獻上今年的收穫。"],"allyAccept":["好，本王與你結盟。諸社的溪岸從此為你的人放行。","本王少與外人結交，你是例外，望你別讓本王失望。"],"allyReject":["本王的盟友只有大肚溪兩岸的諸社，外人免談。","結盟就是要開門，本王還不打算為你開這扇門。"]}},{"name":"莫那魯道","title":"賽德克族馬赫坡社頭目","era":"1930 年","tone":"沉痛堅毅、以祖訓與族人尊嚴為念的獵人頭目","portrait":"ti-historical-age3","lines":{"intro":["我是馬赫坡社的頭目莫那魯道，獵場與祖靈是我的一切。","遠方的君主，你若敬重祖訓與土地，我們可以說話。"],"contact":["你的人踏進了我族的獵場，這裡的山每一寸都有祖靈。","看見我的部落了？記住，這片山不是誰的財產。"],"war":["你奪走我族的獵場與尊嚴，今日我以祖訓之名宣戰。","族人不能一輩子低頭，我寧願站著面對你。"],"warReply":["你要戰？我族的男人自小便在山裡打獵，不怕你。","來吧。祖靈在看，彩虹橋的另一端沒有懦夫。"],"peace":["我不願族人的孩子再失去父親，我們暫且停手吧。","若你肯歸還獵場、尊重祖訓，我願放下獵刀談和。"],"accept":["好，我答應。祖靈為證，只要你守約，我便守約。","族人可以暫時休息了，願你言而有信。"],"reject":["你嘴裡說和平，手裡卻還握著我族的獵場，我不信。","祖訓教我們分辨真心與假意，你的提議我不能接受。"],"rebuff":["你拒絕了？那我只能繼續守在山上，等你回心轉意。","和平不是求來的，我族會用自己的方式守住家園。"],"betray":["你的人又闖進我族的獵場，那份誓約已經不算數了。","我曾相信你的話，如今祖靈告訴我，該拿起獵刀了。"],"truceEnd":["休戰結束了，山上的霧散去，該看清彼此的路了。","約定的日子已過，往後每一步，都要對得起祖靈。"],"attacking":["馬赫坡的男人已經出發了，這是為了族人的尊嚴。","我族的獵人熟悉每一道山脊，你的城牆擋不住山風。"],"attacked":["部落已被圍困，但真正的賽德克人，到最後都不會低頭。","家屋燒了，獵場沒了，可祖靈還在我身後。"],"defeated":["我要走過彩虹橋去見祖靈了，請讓我的族人留在山上。","山會記得我們，這片獵場永遠屬於祖靈。"],"victory":["族人守住了獵場，我向祖靈報告：我們沒有低頭。","戰事結束了。你走吧，這片山從來不需要主人。"],"allyAccept":["好，我族與你結盟。獵場的路為你敞開，祖靈為證。","能有一個尊重祖訓的朋友，是族人的福氣。"],"allyReject":["我族的路要自己走，結盟的事，恕我婉拒。","你還不明白祖訓的分量，我不能把族人的命運交給你。"]}}]},"generic":{"modern-tw":{"name":"台灣總統","title":"總統府","tone":"溫和務實、海島自信、重視民主與人民","portrait":"tw-modern","lines":{"intro":["你好，我是台灣總統。這座島雖小，志氣不小。","台灣向各國致意，願以科技與善意結交朋友。"],"contact":["你看到的港都，是台灣人民用雙手打拚出來的。","歡迎來到我們的城市，夜市的燈火還亮著呢。"],"war":["台灣不願戰爭，但為了守護家園，我們別無選擇。","談判已經失敗，台灣今日正式向貴國宣戰。"],"warReply":["你選擇了戰爭？這座島從來沒有向誰低過頭。","台灣人民會團結起來，大海就是我們的城牆。"],"peace":["打仗只會讓兩邊的百姓受苦，我們停火談談吧。","台灣提議停戰，把資源留給建設，不留給砲火。"],"accept":["好，台灣接受。願和平從今天開始生根。","感謝你的誠意，台灣願與貴國攜手前行。"],"reject":["抱歉，你的條件台灣人民無法接受。","停戰可以談，但不是在這種條件之下。"],"rebuff":["很遺憾你拒絕了，台灣的大門仍然敞開。","我尊重你的決定，但請記得，和平永遠有機會。"],"betray":["貴國的舉動已越過紅線，台灣不得不重啟戰端。","停戰協議已被貴國踐踏，台灣將採取行動。"],"truceEnd":["休戰期結束了，台灣已做好一切準備。","和平的時間到此為止，接下來各憑本事。"],"attacking":["台灣的部隊已經出發，請貴國好自為之。","我們的艦隊已經出海，這是你逼我們的。"],"attacked":["總統府的燈火還亮著，台灣人不會輕易放棄。","城牆快守不住了，但這座島的意志還在。"],"defeated":["台灣倒下了，但這片土地的故事還沒結束。","請善待我的人民，他們比我更愛這座島。"],"victory":["戰爭結束了。台灣贏了，但我不會慶祝苦難。","勝利屬於台灣人民，願世界從此少一場戰爭。"],"allyAccept":["台灣很榮幸與貴國結盟，朋友之間互相照應。","好，從今天起我們是盟友，一起守護和平。"],"allyReject":["謝謝你的邀請，但台灣現在還不適合結盟。","結盟是大事，台灣需要更多時間觀察貴國。"]}},"modern-cn":{"name":"中國主席","title":"中央政府","tone":"沉穩含蓄、引經據典、大國氣度","portrait":"cn-modern","lines":{"intro":["有朋自遠方來，不亦樂乎。我是中國主席。","中國向貴國問好，五千年文明願與世界共榮。"],"contact":["你看到的城牆，見證了無數朝代的興衰。","歡迎來到中國的城市，這裡的歷史比你想的更長。"],"war":["忍耐是有限度的，中國今日正式向貴國宣戰。","貴國一再挑釁，中國不得不以戰止戰。"],"warReply":["貴國向中國宣戰？這片土地從不畏懼風雨。","兵者，國之大事。既然你已決定，中國奉陪到底。"],"peace":["化干戈為玉帛，中國提議雙方停火。","戰火傷人傷己，不如坐下來喝杯茶談談。"],"accept":["好，中國同意。和則兩利，鬥則俱傷。","貴國有此誠意，中國願共築長久和平。"],"reject":["貴國的條件缺乏誠意，中國無法接受。","現在談停戰，時機未到。"],"rebuff":["貴國拒絕了，很可惜。中國會記住今天。","既然如此，中國尊重貴國的選擇。"],"betray":["貴國屢次違約，停戰協議自今日起失效。","中國的耐心已盡，重啟戰端，責任在貴國。"],"truceEnd":["休戰期已過，中國已整軍完畢。","和平的時限到了，接下來看各自的實力。"],"attacking":["中國的大軍已經開拔，貴國請早作打算。","兵貴神速，我軍此刻已在路上。"],"attacked":["京城告急，但中國的歷史從未因一戰而終。","城牆將傾，我仍相信人民會撐住這片土地。"],"defeated":["中國敗了，但文明的火種不會熄滅。","勝敗乃兵家常事，願你善待這片土地的人民。"],"victory":["戰爭結束了，中國勝利。願天下從此太平。","勝利屬於人民。貴國若願重建，中國不吝相助。"],"allyAccept":["中國同意結盟。四海之內皆兄弟，願共進退。","好，兩國結為盟友，往後互為依靠。"],"allyReject":["結盟之事，中國尚需慎重考慮。","貴國的提議中國心領了，但現在不是時候。"]}},"modern-jp":{"name":"日本首相","title":"內閣府","tone":"禮貌謹慎、含蓄內斂、四季與櫻花意象","portrait":"jp-modern","lines":{"intro":["初次見面，請多指教。我是日本首相。","日本向貴國致上問候，願彼此和睦相處。"],"contact":["你看到的城市，春天時櫻花會開滿街道。","歡迎光臨。日本的城市，秩序與美是我們的驕傲。"],"war":["非常遺憾，日本不得不向貴國宣戰。","我們已盡力克制，但貴國逼得日本別無選擇。"],"warReply":["貴國宣戰了嗎？日本會以全部的決心回應。","櫻花凋落也有其尊嚴，日本絕不會不戰而降。"],"peace":["戰爭讓兩國人民都受苦了，日本提議停火。","請容我提議，讓我們放下武器，重新對話。"],"accept":["日本接受。感謝貴國的寬容與智慧。","好的，日本同意。願兩國關係如春日般溫暖。"],"reject":["很抱歉，這樣的條件日本無法答應。","日本感謝貴國的提議，但目前難以接受。"],"rebuff":["我明白了。日本尊重貴國的判斷。","真是遺憾，不過日本會靜候貴國改變心意。"],"betray":["貴國背棄了約定，日本只好重啟戰端。","信義既失，停戰協議已無意義，日本將再度出兵。"],"truceEnd":["休戰期結束了。日本已做好萬全準備。","平靜的時光到此為止，接下來請各自努力。"],"attacking":["日本的部隊已經出發，請貴國做好準備。","我軍正朝貴國前進，這是萬不得已的決定。"],"attacked":["首都陷入危機，但日本人民不會輕言放棄。","城牆搖搖欲墜，日本仍會堅持到最後一刻。"],"defeated":["日本輸了。願櫻花明年依然為這片土地盛開。","我承認失敗。請善待我的國民，拜託了。"],"victory":["戰爭結束了，日本勝利。願逝者安息，生者和平。","勝利屬於日本。貴國若願重建，日本願伸出援手。"],"allyAccept":["日本很榮幸與貴國結盟，今後請多多關照。","好的，兩國結為盟友。願友誼長存。"],"allyReject":["非常抱歉，日本目前無法與貴國結盟。","結盟是重大決定，日本需要更多時間考慮。"]}},"modern-kr":{"name":"韓國總統","title":"總統府","tone":"熱情堅毅、重情義、韌性十足","portrait":"kr-modern","lines":{"intro":["你好，我是韓國總統。很高興認識新朋友。","韓國向貴國致意，願以真誠開啟兩國友誼。"],"contact":["你看到的城市，晚上的燈光比白天還熱鬧。","歡迎來到韓國，這裡的人熱情，辣味也不含糊。"],"war":["韓國已忍無可忍，今日正式向貴國宣戰。","我們珍惜和平，但韓國從不畏懼保衛自己。"],"warReply":["你向韓國宣戰？這個民族從不向威脅低頭。","好，韓國接下這一戰。我們的意志比鋼還硬。"],"peace":["打下去只有兩敗俱傷，韓國提議停火。","讓我們停下來吧，人民需要的是安穩的生活。"],"accept":["好，韓國接受。今天是個值得紀念的日子。","韓國同意。願和平像春天一樣，來了就不走。"],"reject":["抱歉，這樣的條件韓國無法接受。","韓國要的是公平的和平，不是屈辱的停火。"],"rebuff":["你拒絕了？韓國會記住這份誠意被怎麼對待。","很可惜，不過韓國的大門不會關上。"],"betray":["貴國違背了承諾，韓國不得不再度宣戰。","停戰協議已被貴國撕毀，韓國將以行動回應。"],"truceEnd":["休戰期結束了，韓國已經準備好了。","和平的時間到此為止，接下來全力以赴。"],"attacking":["韓國的部隊已經出發，請貴國做好準備。","我軍正朝貴國前進，這場仗韓國不會退縮。"],"attacked":["首都告急，但韓國人民從不輕易認輸。","城牆快撐不住了，但我們的心還沒有倒下。"],"defeated":["韓國倒下了，但這個民族的歌聲不會停止。","我輸了。請善待我的人民，他們值得更好的未來。"],"victory":["戰爭結束了，韓國勝利。願和平從此長駐。","勝利屬於韓國人民。貴國若願重建，韓國會幫忙。"],"allyAccept":["韓國很高興與貴國結盟，朋友就是要互相幫忙。","好，從今天起我們是盟友，有難一起扛。"],"allyReject":["謝謝你的邀請，但韓國現在無法結盟。","結盟是大事，韓國需要再觀察一段時間。"]}},"modern-mn":{"name":"蒙古總統","title":"總統府","tone":"草原豪邁、敬天重信、馬背民族的坦率","portrait":"mn-modern","lines":{"intro":["你好，我是蒙古總統。草原上的人向你問候。","蒙古向貴國致意，長生天保佑遠方的客人。"],"contact":["你看到的城市，四周是望不到邊的草原。","歡迎來到蒙古，這裡的天空比任何地方都大。"],"war":["蒙古人敬天也敬信義，貴國兩者皆違，開戰吧。","草原的風已經轉向了，蒙古今日向貴國宣戰。"],"warReply":["你向蒙古宣戰？馬背上的民族從不怕遠征。","好，蒙古接受挑戰。祖先的馬蹄聲會與我們同在。"],"peace":["草原夠大，容得下兩個國家。蒙古提議停火。","馬需要休息，人也一樣。我們停戰吧。"],"accept":["好，蒙古接受。長生天見證今天的約定。","蒙古同意。草原上的承諾，比石頭還重。"],"reject":["這樣的條件，蒙古人不會點頭。","抱歉，蒙古現在還不想停下馬蹄。"],"rebuff":["你拒絕了？草原上的人會記住這份回答。","很可惜，不過蒙古的帳篷永遠為客人留門。"],"betray":["貴國背棄了誓言，蒙古人最痛恨失信之人。","停戰協議已成廢紙，蒙古的鐵騎將再度出動。"],"truceEnd":["休戰期結束了，蒙古的馬已經吃飽了草。","和平的時間到此為止，草原上的風開始吹了。"],"attacking":["蒙古的部隊已經出發，草原的風會替我們開路。","馬蹄聲已經響起，我軍正朝貴國前進。"],"attacked":["首都告急，但蒙古人的心永遠向著草原。","城牆快倒了，但只要還有一匹馬，蒙古就不算輸。"],"defeated":["蒙古倒下了，但草原的風會記得我們的名字。","我輸了。請善待草原上的人民，讓他們繼續放牧。"],"victory":["戰爭結束了，蒙古勝利。長生天保佑這片土地。","勝利屬於草原。貴國若願重建，蒙古願分享牛羊。"],"allyAccept":["蒙古願與貴國結盟，草原上的兄弟共飲一碗奶茶。","好，從今天起我們是盟友，馬鞍並肩前行。"],"allyReject":["謝謝你的邀請，但蒙古現在還不想結盟。","結盟是大事，草原上的人需要先看清楚對方。"]}},"modern-in":{"name":"印度總理","title":"總理辦公室","tone":"哲思沉穩、崇尚非暴力、多元包容","portrait":"in-modern","lines":{"intro":["你好，我是印度總理。願和平與你同在。","印度向貴國致意，十幾億人民歡迎新朋友。"],"contact":["你看到的城市，色彩比彩虹還多。","歡迎來到印度，這裡的香料與歌聲一樣濃烈。"],"war":["印度崇尚非暴力，但也不容許他人踐踏。開戰吧。","貴國一再挑釁，印度今日正式宣戰。"],"warReply":["你向印度宣戰？這片土地的耐心比恆河還長。","好，印度接受。我們的人民會像大象一樣站穩。"],"peace":["以眼還眼只會讓世界盲目，印度提議停火。","戰爭無法帶來真正的勝利，讓我們停下來吧。"],"accept":["好，印度接受。和平是最偉大的力量。","印度同意。願兩國的友誼如恆河長流。"],"reject":["抱歉，這樣的條件印度無法接受。","印度渴望和平，但不是不公平的和平。"],"rebuff":["你拒絕了。印度會繼續等待理智回來的那天。","很可惜，不過印度相信時間會改變一切。"],"betray":["貴國背棄了承諾，印度不得不重啟戰端。","停戰協議被貴國撕毀，印度只能以行動回應。"],"truceEnd":["休戰期結束了，印度已經準備好了。","和平的時間到此為止，接下來各憑實力。"],"attacking":["印度的部隊已經出發，請貴國做好準備。","我軍正朝貴國前進，這不是印度想要的路。"],"attacked":["首都告急，但印度的靈魂不在城牆上，在人民心中。","城牆快倒了，但這片古老的土地見過更多風雨。"],"defeated":["印度倒下了，但真理不會因此消失。","我輸了。請善待我的人民，他們的信仰比我堅定。"],"victory":["戰爭結束了，印度勝利。願所有生命都得安寧。","勝利屬於印度。貴國若願重建，印度願伸出援手。"],"allyAccept":["印度很榮幸與貴國結盟，願我們一同走向光明。","好，從今天起我們是盟友，共享茶香與智慧。"],"allyReject":["謝謝你的邀請，但印度目前選擇不結盟。","結盟是大事，印度需要更多時間思考。"]}},"modern-ru":{"name":"俄羅斯總統","title":"聯邦政府","tone":"冷靜強硬、言簡意賅、冬天與廣袤土地意象","portrait":"ru-modern","lines":{"intro":["你好，我是俄羅斯總統。這片土地大到裝得下冬天。","俄羅斯向貴國致意。遠方的鄰居，希望我們互相尊重。"],"contact":["你看到的城市，冬天的雪會把屋頂染成白色。","歡迎來到俄羅斯。這裡的冬天很長，人的意志更長。"],"war":["俄羅斯的耐心已經用完，今日正式向貴國宣戰。","貴國選擇了對抗，俄羅斯會讓你明白這個選擇的代價。"],"warReply":["你向俄羅斯宣戰？歷史上很多人試過，冬天會回答你。","好。俄羅斯從不害怕戰爭，只害怕沒有對手。"],"peace":["戰爭消耗的是雙方的未來，俄羅斯提議停火。","俄羅斯願意停戰。冬天太冷，不適合打仗。"],"accept":["好，俄羅斯接受。這是明智的決定。","俄羅斯同意。願這份協議比西伯利亞的凍土還牢固。"],"reject":["這樣的條件，俄羅斯不會接受。","現在談停戰？俄羅斯還沒有理由停下來。"],"rebuff":["你拒絕了。俄羅斯會記住這個決定。","既然如此，俄羅斯尊重你的選擇，也會準備後果。"],"betray":["貴國違反了協議，俄羅斯不再受停戰約束。","停戰協議已經失效。俄羅斯將重新部署軍隊。"],"truceEnd":["休戰期結束了。俄羅斯已經準備就緒。","和平的時間到了盡頭，接下來憑實力說話。"],"attacking":["俄羅斯的部隊已經出發，貴國最好做好準備。","我軍正朝貴國推進，這是你自己招來的。"],"attacked":["首都告急，但俄羅斯的土地太大，你占不完。","城牆快倒了，但俄羅斯人不會在自己的家門口低頭。"],"defeated":["俄羅斯倒下了。但冬天還會再來，每一年都會。","我輸了。請善待這片土地的人民，他們吃過太多苦。"],"victory":["戰爭結束了，俄羅斯勝利。願和平久一點。","勝利屬於俄羅斯。貴國若願重建，俄羅斯不會為難。"],"allyAccept":["俄羅斯同意結盟。朋友不多，但每一個都算數。","好，從今天起我們是盟友。俄羅斯說到做到。"],"allyReject":["結盟？俄羅斯現在還沒有這個打算。","謝謝你的提議，但俄羅斯習慣自己走路。"]}},"modern-gb":{"name":"英國首相","title":"首相官邸","tone":"紳士幽默、含蓄鎮定、海洋與雨天意象","portrait":"gb-modern","lines":{"intro":["午安，我是英國首相。今天天氣不錯，適合認識新朋友。","英國向貴國致意。海洋隔開了我們，也連接了我們。"],"contact":["你看到的城市，常常下雨，但從不缺故事。","歡迎來到英國。請帶把傘，還有喝茶的耐心。"],"war":["英國已盡力保持風度，但現在必須向貴國宣戰。","很遺憾走到這一步。英國今日正式宣戰。"],"warReply":["你向英國宣戰？這座島擋過的風浪，比你想像得多。","好吧。英國會保持冷靜，繼續前進。"],"peace":["打仗實在太不文明了，英國提議停火，喝杯茶如何？","英國提議停戰。理性的人應該懂得何時該收手。"],"accept":["好，英國接受。這是個文明的決定。","英國同意。願這份協議像下午茶一樣準時而持久。"],"reject":["恕我直言，這樣的條件英國無法接受。","英國感謝貴國的提議，但答案是否。"],"rebuff":["你拒絕了？真可惜，茶都泡好了。","我明白了。英國尊重你的決定，也會做好準備。"],"betray":["貴國違背了君子協定，英國不得不重啟戰端。","停戰協議已被貴國撕毀。英國會以行動回應，而非言語。"],"truceEnd":["休戰期結束了。英國已經準備妥當。","和平的時間到此為止。接下來，各自展現風度吧。"],"attacking":["英國的艦隊已經出港，請貴國做好準備。","我軍正朝貴國前進。這不是英國的本意，但必須完成。"],"attacked":["首都告急，但英國人向來在最壞的時候最鎮定。","城牆快倒了，但英國不會在自己的島上投降。"],"defeated":["英國輸了。願歷史寫下我們曾經體面地抵抗。","我承認失敗。請善待我的人民，他們配得上尊重。"],"victory":["戰爭結束了，英國勝利。願海洋從此只載商船。","勝利屬於英國。貴國若願重建，英國樂意提供協助。"],"allyAccept":["英國很樂意與貴國結盟。盟友之間，茶要一起喝。","好，從今天起我們是盟友。英國的承諾不會落空。"],"allyReject":["謝謝你的邀請，但英國目前傾向保持獨立。","結盟是大事，英國需要更多時間審慎評估。"]}},"modern-fr":{"name":"法國總統","title":"總統府","tone":"優雅浪漫、熱情、自由平等博愛","portrait":"fr-modern","lines":{"intro":["你好，我是法國總統。自由、平等、博愛，向你問候。","法國向貴國致意。願我們的相遇像一首好詩。"],"contact":["你看到的城市，每條街道都有麵包香和畫家。","歡迎來到法國。這裡的人談藝術，也談政治。"],"war":["法國熱愛和平，但更熱愛自由。今日正式向貴國宣戰。","貴國的行為已無法容忍，法國決定宣戰。"],"warReply":["你向法國宣戰？為自由奮鬥過的人民，不會退縮。","好，法國接受。我們會用整個民族的熱情回應你。"],"peace":["戰爭是最醜陋的藝術，法國提議停火。","讓我們放下武器，把時間留給麵包與音樂。"],"accept":["好，法國接受。和平比任何勝利都更優雅。","法國同意。願這份協議像老橡樹一樣越來越穩固。"],"reject":["抱歉，這樣的條件法國無法接受。","法國要的是有尊嚴的和平，而不是屈辱的停火。"],"rebuff":["你拒絕了？真可惜，法國的誠意被辜負了。","我明白了。法國尊重你的選擇，也會做好準備。"],"betray":["貴國背棄了承諾，法國不得不重啟戰端。","停戰協議已被貴國撕毀。法國將為榮譽而戰。"],"truceEnd":["休戰期結束了。法國已經準備好了。","和平的時間到此為止。接下來，各自展現實力吧。"],"attacking":["法國的部隊已經出發，請貴國做好準備。","我軍正朝貴國前進。這不是法國的本意，但必須完成。"],"attacked":["首都告急，但法國人民的熱情不會被城牆困住。","城牆快倒了，但自由的火焰還在人民心中燃燒。"],"defeated":["法國倒下了。但自由的種子，會在別處發芽。","我輸了。請善待我的人民，他們值得美好的生活。"],"victory":["戰爭結束了，法國勝利。願世界重新學會欣賞美。","勝利屬於法國。貴國若願重建，法國樂意分享經驗。"],"allyAccept":["法國很榮幸與貴國結盟。朋友之間，要一起吃晚餐。","好，從今天起我們是盟友。法國的友誼熱烈而長久。"],"allyReject":["謝謝你的邀請，但法國目前選擇保持獨立。","結盟是大事，法國需要更多時間思考。"]}},"modern-de":{"name":"德國總理","title":"聯邦總理府","tone":"嚴謹務實、守時守信、從歷史學到珍惜和平","portrait":"de-modern","lines":{"intro":["你好，我是德國總理。準時、守信，是我們的原則。","德國向貴國致意。歷史教會我們珍惜和平。"],"contact":["你看到的城市，每條街道都乾淨得像剛畫好的圖。","歡迎來到德國。火車準時，人也準時。"],"war":["德國已盡一切外交努力，今日不得不向貴國宣戰。","貴國的行為已無法容忍。德國正式宣戰。"],"warReply":["你向德國宣戰？我們會用精確和紀律回應你。","好，德國接受。我們從歷史學到的，不只是和平。"],"peace":["德國比誰都清楚戰爭的代價，我們提議停火。","戰爭是最沒有效率的解決方式。德國提議停戰。"],"accept":["好，德國接受。理性終於戰勝了衝動。","德國同意。這份協議，我們會嚴格遵守。"],"reject":["抱歉，這樣的條件德國無法接受。","德國要的是可以執行的和平，不是空洞的承諾。"],"rebuff":["你拒絕了。德國會把這個結果記錄在案。","我明白了。德國尊重你的決定，並會調整計畫。"],"betray":["貴國違反了協議，德國不得不重啟戰端。","停戰協議已被貴國撕毀。德國將依計畫行動。"],"truceEnd":["休戰期結束了。德國的準備工作已經完成。","和平的時間到此為止。接下來，按計畫進行。"],"attacking":["德國的部隊已經出發，一切按照時間表進行。","我軍已經上路。德國做事，向來不拖泥帶水。"],"attacked":["首都告急，但德國人在廢墟上重建過不只一次。","城牆快倒了，但德國的意志不會跟著倒下。"],"defeated":["德國倒下了。願下一次的重建，能比上一次更好。","我承認失敗。請善待我的人民，他們只想好好工作。"],"victory":["戰爭結束了，德國勝利。願這是最後一場戰爭。","勝利屬於德國。貴國若願重建，德國願提供技術。"],"allyAccept":["德國同意結盟。合約已擬好，我們會準時履行。","好，從今天起我們是盟友。德國的承諾說到做到。"],"allyReject":["謝謝你的邀請，但德國目前不打算結盟。","結盟需要詳細評估，德國現在無法給你答案。"]}},"modern-us":{"name":"美國總統","title":"白宮","tone":"自信直率、樂觀大器、強調自由","portrait":"us-modern","lines":{"intro":["你好，我是美國總統。很高興認識你，朋友。","美國向貴國致意。自由的國度，歡迎所有願意交朋友的人。"],"contact":["你看到的城市，高樓比山還高，夢想比樓還高。","歡迎來到美國。這裡什麼都大，包括我們的胃口。"],"war":["美國已經給過機會了。今日，我們正式向貴國宣戰。","自由不容威脅。美國決定宣戰。"],"warReply":["你向美國宣戰？好，這下你會知道什麼叫全力以赴。","美國接受挑戰。我們從不挑起戰爭，但一定會結束它。"],"peace":["打夠了吧？美國提議停火，把錢花在更好的地方。","美國提議停戰。真正的強者知道什麼時候該握手。"],"accept":["好，美國接受。這是雙贏的決定。","美國同意。今天是好日子，我們一起往前看。"],"reject":["抱歉，這樣的條件美國無法接受。","美國不會簽一份對自己不利的協議。"],"rebuff":["你拒絕了？沒關係，美國的提議不會永遠有效。","我明白了。美國尊重你的選擇，也會準備下一步。"],"betray":["貴國違背了協議，美國不得不重啟戰端。","停戰協議已被貴國撕毀。美國會讓你為此付出代價。"],"truceEnd":["休戰期結束了。美國已經準備好了。","和平的時間到此為止。接下來，看誰的實力更強。"],"attacking":["美國的部隊已經出發，貴國最好做好準備。","我軍正朝貴國前進。這不是美國想要的，但我們會做完。"],"attacked":["首都告急，但美國人從不在困難面前低頭。","城牆快倒了，但星條旗還在飄，我們就還沒輸。"],"defeated":["美國倒下了。但自由的理念，不會跟著一起倒。","我輸了。請善待我的人民，他們相信明天會更好。"],"victory":["戰爭結束了，美國勝利。願自由從此照亮每個角落。","勝利屬於美國。貴國若願重建，美國願意幫一把。"],"allyAccept":["美國很高興與貴國結盟。朋友有難，我們一定到。","好，從今天起我們是盟友。美國說話算話。"],"allyReject":["謝謝你的邀請，但美國現在不打算結盟。","結盟是大事，美國需要先確認貴國的誠意。"]}},"modern-au":{"name":"澳洲總理","title":"聯邦政府","tone":"隨和開朗、陽光海灘、講公平不好欺負","portrait":"au-modern","lines":{"intro":["嗨，我是澳洲總理。南半球的陽光向你問好。","澳洲向貴國致意。我們離得遠，但心不遠。"],"contact":["你看到的城市，海灘就在市中心旁邊。","歡迎來到澳洲。小心袋鼠，牠們有時會跳上馬路。"],"war":["澳洲人隨和，但不是好欺負。今日正式向貴國宣戰。","貴國的行為已經越線，澳洲決定宣戰。"],"warReply":["你向澳洲宣戰？好，這片大陸的人從不怕烈日和風暴。","澳洲接受挑戰。我們打球認真，打仗也一樣。"],"peace":["打仗太浪費好天氣了，澳洲提議停火。","澳洲提議停戰。人生苦短，不如去海邊走走。"],"accept":["好，澳洲接受。這才是聰明的做法。","澳洲同意。來，一起烤肉慶祝和平吧。"],"reject":["抱歉，這樣的條件澳洲無法接受。","澳洲人講公平，這份提議不夠公平。"],"rebuff":["你拒絕了？沒關係，澳洲的門一直開著。","我明白了。澳洲尊重你的決定，也會做好準備。"],"betray":["貴國違背了承諾，澳洲不得不重啟戰端。","停戰協議已被貴國撕毀。澳洲會用行動回應。"],"truceEnd":["休戰期結束了。澳洲已經準備好了。","和平的時間到此為止。接下來，各憑本事吧。"],"attacking":["澳洲的部隊已經出發，請貴國做好準備。","我軍正跨海而來。澳洲人不常出手，出手就認真。"],"attacked":["首都告急，但澳洲人在乾旱和野火裡都撐過來了。","城牆快倒了，但這片大陸的人不會輕易認輸。"],"defeated":["澳洲倒下了。但南半球的太陽，明天還是會升起。","我輸了。請善待我的人民，他們只想好好過日子。"],"victory":["戰爭結束了，澳洲勝利。願海洋從此平靜。","勝利屬於澳洲。貴國若願重建，澳洲願意幫忙。"],"allyAccept":["澳洲很高興與貴國結盟。朋友就是要互相照應。","好，從今天起我們是盟友。澳洲的朋友不會孤單。"],"allyReject":["謝謝你的邀請，但澳洲現在不打算結盟。","結盟是大事，澳洲需要再觀察一陣子。"]}},"fantasy":{"name":"國主","title":"架空王國","tone":"奇幻史詩、古龍與符文、以本王自稱","portrait":"fantasy","lines":{"intro":["遠方的君主，本王以古龍之名向你問候。","王國的城門為你敞開，或為你緊閉，全看你的選擇。"],"contact":["你看到的高塔，是先王以魔法與石頭築成的。","歡迎來到王國。城牆上的符文，已守護此地千年。"],"war":["先王之劍已出鞘，本王今日向你宣戰！","你已觸怒王國的守護神。戰鼓，響起吧！"],"warReply":["你敢向王國宣戰？古龍的火焰會回答你。","很好。王國的騎士等這一天，已經等了很久。"],"peace":["戰火燒盡的只有百姓的家園。本王提議停戰。","讓劍回到鞘中吧。王國願與你休戰。"],"accept":["好，本王接受。以古龍之名，此約不破。","王國同意。願魔法之光照亮兩國的和平。"],"reject":["這樣的條件，王國的先祖不會答應。","本王拒絕。劍還沒有磨鈍，何來停戰？"],"rebuff":["你拒絕了？古龍會記住這份傲慢。","很好。既然如此，王國會以劍回應。"],"betray":["你背棄了古龍之名的誓約。王國將再度舉劍！","停戰的符文已被你打碎。戰火，重新點燃！"],"truceEnd":["休戰的咒語已經失效。王國的劍，再度出鞘。","和平的月光落下了。接下來，是刀劍的時代。"],"attacking":["王國的騎士已經出征，古龍在天空為他們引路。","本王的大軍已越過邊境。你的城牆，撐得住嗎？"],"attacked":["王城的符文快熄滅了，但本王仍會站在城牆上。","高塔搖搖欲墜，但王國的靈魂不在石頭裡。"],"defeated":["王國隕落了。願古龍在遠方，記得我們的名字。","本王敗了。請善待我的子民，他們無罪。"],"victory":["戰爭結束了，王國勝利。願先王在天之靈安息。","勝利屬於王國。你若願重建家園，本王不會為難。"],"allyAccept":["本王願與你結盟。古龍見證，兩國同進同退。","好。從今日起，你的敵人就是王國的敵人。"],"allyReject":["結盟？王國的先祖教導本王，勿輕信遠方之人。","本王心領了，但王國暫時不需要盟友。"]}},"scifi":{"name":"執政官","title":"軌道議會","tone":"冷靜理性、數據與系統用語、以本官／議會自稱","portrait":"scifi","lines":{"intro":["軌道議會執政官向你致意。掃描完成，你已列入紀錄。","你好，地表的君主。我在軌道上，看得比你遠。"],"contact":["你看到的，是議會的軌道電梯基地。請勿靠近核心。","歡迎來到議會領地。你的座標已同步至中央系統。"],"war":["外交協議已終止。軌道議會向你宣戰，倒數開始。","談判效率低於預期。議會決定改用武力解決。"],"warReply":["你向議會宣戰？運算結果顯示，你的勝率不高。","收到宣戰訊號。防禦系統已啟動，議會奉陪。"],"peace":["戰爭消耗的能源，足以點亮三座城市。議會提議停火。","數據顯示，停戰對雙方都更有利。請考慮這個方案。"],"accept":["議會接受。協議已寫入系統，即刻生效。","合理的決定。停火協議已上傳至軌道網路。"],"reject":["你的提議不符合議會的最佳利益。拒絕。","運算結果：現在停戰對議會不利。談判中止。"],"rebuff":["你拒絕了。議會已記錄此決定，並重新計算方案。","不合理的選擇，但議會尊重你的自主權。"],"betray":["你違反了協議條款。議會解除停戰狀態，武器重新上線。","信任值已歸零。議會將以最有效率的方式回應。"],"truceEnd":["休戰倒數歸零。議會的武裝系統已解除鎖定。","和平協議已過期。接下來，由實力決定一切。"],"attacking":["議會艦隊已離開軌道，預計抵達時間：很快。","無人機群已出發。你的防線，撐不了多久。"],"attacked":["核心受損百分之八十。但議會的資料，早已備份。","防禦系統即將崩潰。這是本官第一次無法計算結果。"],"defeated":["議會系統關閉。也許，你比運算結果更難預測。","本官承認失敗。請善待軌道上的居民，他們只是公民。"],"victory":["戰爭結束，結果如預測。議會將重新分配資源。","勝利已確認。你若願重建，議會可提供技術支援。"],"allyAccept":["議會同意結盟。你的資料權限已升級為盟友等級。","合作效率最高。從此刻起，議會與你共享防禦網。"],"allyReject":["結盟申請已收到。評估結果：暫不通過。","議會目前不需要盟友。你的請求已存檔。"]}}},"leaders":{},"nationCodes":{"Taiwan Indigenous":"ti"}};
